function resetSqliteConcurrencyProbe({ preserveSchemaCount = false } = {}) {
  assert.equal(sqliteConcurrencyProbe.activeOperations, 0, 'SQLite concurrency probe resets only while idle')
  sqliteConcurrencyProbe.maxActiveOperations = 0
  sqliteConcurrencyProbe.lockViolations.length = 0
  sqliteConcurrencyProbe.operationLog.length = 0
  sqliteConcurrencyProbe.nextFailure = null
  sqliteConcurrencyProbe.nextTransactionPause = null
  if (!preserveSchemaCount) sqliteConcurrencyProbe.conversationSchemaExecutions = 0
}

function pauseNextSqliteConcurrencyTransaction() {
  let notifyStarted
  let release
  const started = new Promise((resolve) => {
    notifyStarted = resolve
  })
  const released = new Promise((resolve) => {
    release = resolve
  })
  sqliteConcurrencyProbe.nextTransactionPause = { notifyStarted, released }
  return { started, release }
}

async function runSqliteConcurrencyNativeOperation(label, operation) {
  if (sqliteConcurrencyProbe.activeOperations > 0) {
    sqliteConcurrencyProbe.lockViolations.push(label)
    throw new Error('database is locked')
  }
  sqliteConcurrencyProbe.activeOperations += 1
  sqliteConcurrencyProbe.maxActiveOperations = Math.max(
    sqliteConcurrencyProbe.maxActiveOperations,
    sqliteConcurrencyProbe.activeOperations,
  )
  sqliteConcurrencyProbe.operationLog.push(`${label}:start`)
  try {
    await Promise.resolve()
    if (sqliteConcurrencyProbe.nextFailure) {
      const failure = sqliteConcurrencyProbe.nextFailure
      sqliteConcurrencyProbe.nextFailure = null
      throw failure
    }
    return await operation()
  } finally {
    sqliteConcurrencyProbe.operationLog.push(`${label}:end`)
    sqliteConcurrencyProbe.activeOperations -= 1
  }
}

function createSqliteConcurrencyTestDatabase() {
  const recordTransactionOperation = async (kind, source) => {
    if (/CREATE TABLE IF NOT EXISTS conversation_records/i.test(source)) {
      sqliteConcurrencyProbe.conversationSchemaExecutions += 1
    }
    sqliteConcurrencyProbe.operationLog.push(`transaction-${kind}`)
    await Promise.resolve()
  }
  const transaction = {
    execAsync: (source) => recordTransactionOperation('exec', source),
    async runAsync(source) {
      await recordTransactionOperation('run', source)
      return { changes: 1, lastInsertRowId: 0 }
    },
    async getFirstAsync(source) {
      await recordTransactionOperation('get-first', source)
      return null
    },
    async getAllAsync(source) {
      await recordTransactionOperation('get-all', source)
      return []
    },
  }
  return {
    execAsync: (source) => runSqliteConcurrencyNativeOperation('exec', async () => {
      if (/CREATE TABLE IF NOT EXISTS conversation_records/i.test(source)) {
        sqliteConcurrencyProbe.conversationSchemaExecutions += 1
      }
    }),
    runAsync: (source) => runSqliteConcurrencyNativeOperation('run', async () => ({
      changes: 1,
      lastInsertRowId: 0,
    })),
    getFirstAsync: () => runSqliteConcurrencyNativeOperation('get-first', async () => null),
    getAllAsync: () => runSqliteConcurrencyNativeOperation('get-all', async () => []),
    withExclusiveTransactionAsync: (work) => runSqliteConcurrencyNativeOperation('transaction', async () => {
      const pause = sqliteConcurrencyProbe.nextTransactionPause
      if (pause) {
        sqliteConcurrencyProbe.nextTransactionPause = null
        pause.notifyStarted()
        await pause.released
      }
      return work(transaction)
    }),
  }
}

function createSqliteWebPersistenceTestDatabase() {
  const executor = {
    async execAsync() {
      return undefined
    },
    async runAsync(source, ...parameters) {
      if (/INSERT INTO web_runtime_probe/i.test(source)) {
        sqliteWebPersistenceProbe.rows.push({ id: parameters[0] })
      }
      return { changes: 1, lastInsertRowId: sqliteWebPersistenceProbe.rows.length }
    },
    async getFirstAsync(source, ...parameters) {
      if (/FROM web_runtime_probe/i.test(source)) {
        return sqliteWebPersistenceProbe.rows.find((row) => row.id === parameters[0]) ?? null
      }
      return null
    },
    async getAllAsync(source) {
      return /FROM web_runtime_probe/i.test(source)
        ? sqliteWebPersistenceProbe.rows.map((row) => ({ ...row }))
        : []
    },
  }
  return {
    ...executor,
    async withExclusiveTransactionAsync() {
      sqliteWebPersistenceProbe.exclusiveTransactions += 1
      throw new Error('Exclusive transactions are unavailable on web.')
    },
    async withTransactionAsync(work) {
      sqliteWebPersistenceProbe.transactions += 1
      await work()
    },
  }
}

