function localModelFixturePath(modelId, filePath) {
  return path.join(root, 'assets', 'models', modelId, ...filePath.split('/'))
}

function localModelDownloadUrl(model, filePath) {
  return `${model.downloadBaseUrl.replace(/\/+$/, '')}/${filePath.replace(/^\/+/, '')}`
}

function localModelMirrorUrl(model, mirrorBaseUrl, filePath) {
  const official = new URL(model.downloadBaseUrl)
  const officialPath = official.pathname.replace(/^\/+|\/+$/g, '')
  return `${mirrorBaseUrl.replace(/\/+$/, '')}/${officialPath}/${filePath.replace(/^\/+/, '')}`
}

function resetLocalModelFileMocks() {
  localFileFixtures.clear()
  localDownloadFixtures.clear()
  localFileReadRequests.length = 0
  localFileOperations.length = 0
  documentPickerRequests.length = 0
  launchedIntents.length = 0
  sharedFiles.length = 0
  sqliteOpenRequests.length = 0
  nextDocumentPickerResult = null
  nextImageLibraryResult = null
  nextCameraResult = null
  nextManipulateResultFactory = null
  nextSqliteOpenError = null
  nextReadDirectoryEntries = null
  nextLocalModelPublishError = null
  nextLocalFileReadError = null
  sharingAvailable = false
  supportedCpuArchitectures.splice(0, supportedCpuArchitectures.length, 'arm64-v8a', 'armeabi-v7a')
  expoDeviceModuleAvailable = true
  reactNativePlatform.OS = 'test'
  resetAsyncStorageFaults()
  resetSecureStorageFaults()
}

async function assertPortableImportRecoveryBehavior() {
  const previousMemoryRows = contextMemoryRows.map((row) => ({ ...row }))
  const previousConversationRecords = conversationRecords.map((row) => ({ ...row }))
  const previousCompactStateRows = compactStateRows.map((row) => ({ ...row }))
  const previousPortableImportRecoveryBlobRows = new Map(portableImportRecoveryBlobRows)
  const previousMemoryStorage = new Map(memoryStorage)
  const previousSecureStorage = new Map(secureStorage)
  resetLocalModelFileMocks()

  try {
    const isolatedProvider = createExpoSqliteDatabaseProvider({ databaseName: 'portable-import-isolated.db' })
    const firstDatabase = await isolatedProvider.get()
    const secondDatabase = await isolatedProvider.get()
    assert.strictEqual(secondDatabase, firstDatabase, 'one platform provider reuses its isolated database promise')
    assert.deepEqual(
      sqliteOpenRequests,
      [{
        name: 'portable-import-isolated.db',
        options: {
          useNewConnection: true,
          finalizeUnusedStatementsBeforeClosing: false,
        },
      }],
      'platform SQLite opens one isolated native connection without Expo close-time FTS statement sweeping',
    )

    resetLocalModelFileMocks()
    nextDocumentPickerResult = { canceled: true, assets: [] }
    assert.deepEqual(
      await importFromJsonFileDetailed(),
      { ok: false, kind: 'invalid', reason: 'selection_cancelled' },
      'portable import distinguishes explicit picker cancellation',
    )

    resetLocalModelFileMocks()
    nextDocumentPickerResult = () => {
      throw new Error('picker unavailable')
    }
    assert.deepEqual(
      await importFromJsonFileDetailed(),
      { ok: false, kind: 'invalid', reason: 'picker_failed' },
      'portable import distinguishes picker failures',
    )

    resetLocalModelFileMocks()
    const unreadableUri = 'file:///tmp/portable-unreadable-import.json'
    localFileFixtures.set(unreadableUri, Buffer.from('{"unreadable":true}', 'utf8'))
    nextLocalFileReadError = new Error('read unavailable')
    nextDocumentPickerResult = {
      canceled: false,
      assets: [{
        uri: unreadableUri,
        name: 'portable-unreadable-import.json',
        mimeType: 'application/json',
        size: localFileFixtures.get(unreadableUri).length,
      }],
    }
    assert.deepEqual(
      await importFromJsonFileDetailed(),
      { ok: false, kind: 'invalid', reason: 'read_failed' },
      'portable import distinguishes bounded file-read failures',
    )
    assert.equal(localFileFixtures.has(unreadableUri), false, 'portable import cleans the temporary picker copy after read failure')

    resetLocalModelFileMocks()
    const invalidStructureUri = 'file:///tmp/portable-invalid-structure.json'
    const invalidStructurePayload = JSON.stringify({ unexpected: true })
    localFileFixtures.set(invalidStructureUri, Buffer.from(invalidStructurePayload, 'utf8'))
    nextDocumentPickerResult = {
      canceled: false,
      assets: [{
        uri: invalidStructureUri,
        name: 'portable-invalid-structure.json',
        mimeType: 'application/json',
        size: Buffer.byteLength(invalidStructurePayload, 'utf8'),
      }],
    }
    assert.deepEqual(
      await importFromJsonFileDetailed(),
      { ok: false, kind: 'invalid', reason: 'invalid_structure' },
      'portable import distinguishes valid JSON with an unsupported structure',
    )

    contextMemoryRows.splice(0, contextMemoryRows.length)
    resetLocalModelFileMocks()
    const validMem0Uri = 'file:///tmp/portable-mem0-import.json'
    const validMem0Payload = JSON.stringify({
      schema: 'islemind.mem0.v1',
      source: 'islemind',
      exported_at: '2026-07-17T08:00:00.000Z',
      filters: { user_id: 'portable-import-test' },
      memories: [{
        id: 'portable-import-pending-memory',
        memory: 'Portable picker imports remain pending for explicit review.',
        user_id: 'portable-import-test',
        metadata: { confidence: 0.87 },
        created_at: '2026-07-17T08:00:00.000Z',
        updated_at: '2026-07-17T08:01:00.000Z',
      }],
    })
    localFileFixtures.set(validMem0Uri, Buffer.from(validMem0Payload, 'utf8'))
    nextDocumentPickerResult = {
      canceled: false,
      assets: [{
        uri: validMem0Uri,
        name: 'portable-mem0-import.json',
        mimeType: 'application/json',
        size: Buffer.byteLength(validMem0Payload, 'utf8'),
      }],
    }
    const successfulImport = await importFromJsonFileDetailed()
    assert.deepEqual(
      successfulImport,
      { ok: true, kind: 'mem0', memories: 1 },
      'picker, bounded UTF-8 read, mem0 parsing, and pending-review persistence succeed together',
    )
    assert.equal(documentPickerRequests.length, 1, 'portable mem0 import performs one picker request')
    assert.equal(localFileReadRequests.some((request) => request.uri === validMem0Uri), true, 'portable mem0 import reads the selected JSON as UTF-8')
    assert.equal(
      contextMemoryRows.find((row) => row.id === 'portable-import-pending-memory')?.status,
      'pending',
      'portable mem0 import keeps imported memory pending until review',
    )
    assert.equal(localFileFixtures.has(validMem0Uri), false, 'portable mem0 import deletes the temporary picker copy')

    resetLocalModelFileMocks()
    const invalidJsonUri = 'file:///tmp/portable-invalid-import.json'
    const invalidJsonPayload = '{"schema":'
    localFileFixtures.set(invalidJsonUri, Buffer.from(invalidJsonPayload, 'utf8'))
    nextDocumentPickerResult = {
      canceled: false,
      assets: [{
        uri: invalidJsonUri,
        name: 'portable-invalid-import.json',
        mimeType: 'application/json',
        size: Buffer.byteLength(invalidJsonPayload, 'utf8'),
      }],
    }
    assert.deepEqual(
      await importFromJsonFileDetailed(),
      { ok: false, kind: 'invalid', reason: 'invalid_json' },
      'portable import distinguishes malformed JSON from persistence failures',
    )

    resetLocalModelFileMocks()
    const rejectedMem0Uri = 'file:///tmp/portable-rejected-import.json'
    localFileFixtures.set(rejectedMem0Uri, Buffer.from(validMem0Payload, 'utf8'))
    nextDocumentPickerResult = {
      canceled: false,
      assets: [{
        uri: rejectedMem0Uri,
        name: 'portable-rejected-import.json',
        mimeType: 'application/json',
        size: Buffer.byteLength(validMem0Payload, 'utf8'),
      }],
    }
    const originalImportMemoriesForReview = portableKnowledgeSnapshot.importMemoriesForReview
    try {
      portableKnowledgeSnapshot.importMemoriesForReview = async () => {
        throw new Error('sqlite path and credential-shaped details must remain internal')
      }
      assert.deepEqual(
        await importFromJsonFileDetailed(),
        { ok: false, kind: 'invalid', reason: 'persistence_failed' },
        'portable import reports repository rejection with a stable redacted failure reason',
      )
    } finally {
      portableKnowledgeSnapshot.importMemoriesForReview = originalImportMemoriesForReview
    }

    resetAsyncStorageFaults()
    const injectedSettingsWriteFailure = new Error('restore storage token=super-secret-value')
    asyncStorageFaults.setItem = (key) => key === '@islemind/settings'
      ? injectedSettingsWriteFailure
      : null
    asyncStorageFaults.removeItem = (key) => key === '@islemind/settings'
      ? injectedSettingsWriteFailure
      : null
    try {
      const failedBackupRestore = await importAllDataDetailed(JSON.stringify({
        app: 'islemind',
        version: 1,
        conversations: [],
        settings: null,
        providers: [],
        exportedAt: Date.parse('2026-07-17T08:01:30.000Z'),
      }))
      assert.deepEqual(
        failedBackupRestore,
        { ok: false, kind: 'invalid', reason: 'persistence_failed' },
        'full backup restore propagates imported AsyncStorage write failure',
      )
      assert.doesNotMatch(JSON.stringify(failedBackupRestore), /super-secret-value/, 'portable restore failure result does not expose raw storage errors')
      assert.equal(
        memoryStorage.has(PORTABLE_IMPORT_RECOVERY_ENVELOPE_STORAGE_KEY),
        true,
        'failed in-process rollback retains the durable whole-import recovery envelope',
      )
    } finally {
      resetAsyncStorageFaults()
    }
    assert.deepEqual(
      await recoverInterruptedPortableImport(),
      { status: 'restored' },
      'startup recovery completes the pending whole-import rollback before later application mutations',
    )

    const credentialProviderId = 'portable-credential-rollback-provider'
    const credentialProviderKey = 'islemind.key.' + credentialProviderId
    const credentialGroupId = 'late-group'
    const credentialGroupKey = credentialProviderKey + '.' + credentialGroupId
    const oldProviderSecret = 'portable-old-provider-secret'
    const oldGroupSecret = 'portable-old-group-secret'
    const newProviderSecret = 'portable-new-provider-secret'
    const newGroupSecret = 'portable-new-group-secret'
    const securePlatformText = 'secure-store-platform-detail-must-stay-internal'
    const storedCredentialProvider = {
      id: credentialProviderId,
      type: 'openai-compatible',
      name: 'Portable credential rollback provider',
      enabled: true,
      models: ['model-old'],
      credentialGroups: [{
        id: credentialGroupId,
        label: 'Late group',
        enabled: true,
        availableModels: ['model-old'],
      }],
    }
    const credentialImportPayload = (credentialGroups) => JSON.stringify({
      app: 'islemind',
      version: 1,
      conversations: [],
      settings: null,
      providers: [{
        id: credentialProviderId,
        type: 'openai-compatible',
        name: 'Portable credential replacement provider',
        enabled: true,
        apiKey: newProviderSecret,
        models: ['model-new'],
        credentialGroups,
      }],
      exportedAt: Date.parse('2026-07-28T12:00:00.000Z'),
    })

    await saveData('PROVIDERS', [storedCredentialProvider])
    secureStorage.set(credentialProviderKey, oldProviderSecret)
    secureStorage.set(credentialGroupKey, oldGroupSecret)
    let injectedCredentialWriteFailure = false
    secureStorageFaults.setItem = (key, value) => {
      if (!injectedCredentialWriteFailure && key === credentialGroupKey && value === newGroupSecret) {
        injectedCredentialWriteFailure = true
        return new Error(securePlatformText + ': ' + newGroupSecret)
      }
      return null
    }
    const failedCredentialWrite = await importAllDataDetailed(credentialImportPayload([{
      id: credentialGroupId,
      label: 'Late replacement group',
      enabled: true,
      apiKey: newGroupSecret,
      availableModels: ['model-new'],
    }]))
    assert.equal(injectedCredentialWriteFailure, true, 'portable credential fixture injects the later group write failure')
    assert.deepEqual(
      failedCredentialWrite,
      { ok: false, kind: 'invalid', reason: 'persistence_failed' },
      'portable import fails closed after a secure credential write failure',
    )
    assert.equal(secureStorage.get(credentialProviderKey), oldProviderSecret, 'failed imported credential write restores the prior provider secret')
    assert.equal(secureStorage.get(credentialGroupKey), oldGroupSecret, 'failed imported credential write restores the prior group secret')
    assert.doesNotMatch(
      JSON.stringify(failedCredentialWrite),
      new RegExp(securePlatformText + '|' + newProviderSecret + '|' + newGroupSecret),
      'credential write failure result omits platform and credential text',
    )

    resetSecureStorageFaults()
    await saveData('PROVIDERS', [storedCredentialProvider])
    secureStorage.set(credentialProviderKey, oldProviderSecret)
    secureStorage.set(credentialGroupKey, oldGroupSecret)
    let injectedCredentialDeleteFailure = false
    secureStorageFaults.deleteItem = (key) => {
      if (!injectedCredentialDeleteFailure && key === credentialGroupKey) {
        injectedCredentialDeleteFailure = true
        return new Error(securePlatformText + ': ' + oldGroupSecret)
      }
      return null
    }
    const failedCredentialDelete = await importAllDataDetailed(credentialImportPayload([]))
    assert.equal(injectedCredentialDeleteFailure, true, 'portable credential fixture injects the later stale-group deletion failure')
    assert.deepEqual(
      failedCredentialDelete,
      { ok: false, kind: 'invalid', reason: 'persistence_failed' },
      'portable import fails closed after a stale credential deletion failure',
    )
    assert.equal(secureStorage.get(credentialProviderKey), oldProviderSecret, 'failed stale-key deletion restores the prior provider secret')
    assert.equal(secureStorage.get(credentialGroupKey), oldGroupSecret, 'failed stale-key deletion preserves the prior group secret')
    assert.doesNotMatch(
      JSON.stringify(failedCredentialDelete),
      new RegExp(securePlatformText + '|' + newProviderSecret + '|' + oldGroupSecret),
      'credential deletion failure result omits platform and credential text',
    )
    resetSecureStorageFaults()

    const atomicRows = []
    let memoryInsertCount = 0
    let importTransactionCount = 0
    const atomicExecutor = {
      async exec() {
        return undefined
      },
      async run(source, parameters = []) {
        if (/INSERT OR REPLACE INTO memories/i.test(source)) {
          memoryInsertCount += 1
          const [id, content, status, conversationId, sourceKind, sourceDetail, confidence, lastHitAt, createdAt, updatedAt] = parameters
          atomicRows.push({ id, content, status, conversationId, sourceKind, sourceDetail, confidence, lastHitAt, createdAt, updatedAt })
          if (memoryInsertCount === 2) throw new Error('injected second memory write failure')
        }
        return { changes: 1, lastInsertRowId: 0 }
      },
      async getFirst(source) {
        return /FROM platform_schema_migrations/i.test(source) ? { version: 2 } : null
      },
      async getAll(source) {
        return /FROM memories/i.test(source) ? atomicRows.map((row) => ({ ...row })) : []
      },
    }
    const atomicDatabase = {
      ...atomicExecutor,
      async transaction(work) {
        importTransactionCount += 1
        const snapshot = atomicRows.map((row) => ({ ...row }))
        try {
          return await work(atomicExecutor)
        } catch (error) {
          atomicRows.splice(0, atomicRows.length, ...snapshot)
          throw error
        }
      },
    }
    const atomicRepository = createSqliteKnowledgeRepository({
      get: async () => atomicDatabase,
    }, {
      clock: { now: () => Date.parse('2026-07-17T08:02:00.000Z') },
      ids: { next: (prefix) => `${prefix}-${memoryInsertCount + 1}` },
    })
    await assert.rejects(
      () => atomicRepository.importMemories([
        { id: 'atomic-import-memory-one', content: 'Atomic import memory one.', status: 'pending', sourceKind: 'imported' },
        { id: 'atomic-import-memory-two', content: 'Atomic import memory two.', status: 'pending', sourceKind: 'imported' },
      ]),
      /injected second memory write failure/,
      'repository import propagates a failed memory write',
    )
    assert.equal(importTransactionCount, 1, 'multi-memory repository import uses one transaction')
    assert.equal(atomicRows.length, 0, 'failed multi-memory repository import rolls back every row')
    await assertWholeImportCoordinatorRecoveryMatrix()
  } finally {
    contextMemoryRows.splice(0, contextMemoryRows.length, ...previousMemoryRows)
    conversationRecords.splice(0, conversationRecords.length, ...previousConversationRecords)
    compactStateRows.splice(0, compactStateRows.length, ...previousCompactStateRows)
    portableImportRecoveryBlobRows.clear()
    for (const [key, value] of previousPortableImportRecoveryBlobRows) {
      portableImportRecoveryBlobRows.set(key, value)
    }
    memoryStorage.clear()
    for (const [key, value] of previousMemoryStorage) memoryStorage.set(key, value)
    secureStorage.clear()
    for (const [key, value] of previousSecureStorage) secureStorage.set(key, value)
    resetSecureStorageFaults()
    resetLocalModelFileMocks()
  }
}

async function assertWholeImportCoordinatorRecoveryMatrix() {
  {
    const harness = createPortableImportCoordinatorHarness(3)
    harness.faults.applyAfter.add('participant-2')
    const result = await harness.coordinator().importPlan({ source: 'late-failure' })
    assert.deepEqual(result, { status: 'rolled_back', cancellationObserved: false }, 'a late participant failure rolls the whole import back')
    assert.deepEqual([...harness.state.values()], ['source-0', 'source-1', 'source-2'], 'late failure restores every participant source')
    assert.deepEqual(harness.restoreOrder, ['participant-2', 'participant-1', 'participant-0'], 'whole-import rollback runs in reverse participant order')
    assert.equal(harness.readEnvelope(), undefined, 'successful rollback removes the recovery envelope')
  }

  {
    const harness = createPortableImportCoordinatorHarness(2)
    await harness.seedApplying(0)
    const result = await harness.coordinator().recover()
    assert.deepEqual(result, { status: 'restored' }, 'restart treats the active participant as possibly committed and restores it')
    assert.deepEqual([...harness.state.values()], ['source-0', 'source-1'], 'restart recovery restores the uncertain active effect')
  }

  {
    const harness = createPortableImportCoordinatorHarness(2)
    const controller = new AbortController()
    harness.faults.afterApply.set('participant-0', () => controller.abort(new Error('cancel after effect')))
    const result = await harness.coordinator().importPlan(
      { source: 'post-effect-cancellation' },
      { signal: controller.signal },
    )
    assert.deepEqual(result, { status: 'rolled_back', cancellationObserved: true }, 'post-effect cancellation rolls back through the non-cancellable recovery path')
    assert.equal(harness.restoreSignals.every((signal) => signal === undefined), true, 'rollback never forwards caller cancellation')
  }

  {
    const harness = createPortableImportCoordinatorHarness(3)
    harness.faults.applyAfter.add('participant-2')
    harness.faults.restoreFailures.set('participant-2', 1)
    const first = await harness.coordinator().importPlan({ source: 'restart-rollback' })
    assert.deepEqual(first, { status: 'recovery_required', cancellationObserved: false }, 'a failed rollback leaves durable recovery required')
    assert.equal(harness.readEnvelope()?.phase, 'rollback_required', 'failed rollback retains its exact durable phase')
    const resumed = await harness.coordinator().recover()
    assert.deepEqual(resumed, { status: 'restored' }, 'a later restart resumes the failed reverse rollback')
    assert.deepEqual(await harness.coordinator().recover(), { status: 'none' }, 'repeated recovery is idempotent after cleanup')
  }

  {
    const harness = createPortableImportCoordinatorHarness(1)
    await harness.seedApplying(0)
    harness.deleteBlob('participant-0')
    assert.deepEqual(await harness.coordinator().recover(), { status: 'recovery_required' }, 'a missing participant backup fails recovery closed')
    assert.equal(harness.state.get('participant-0'), 'target-0', 'missing recovery evidence never overwrites an uncertain target')
  }

  {
    const harness = createPortableImportCoordinatorHarness(1)
    await harness.seedApplying(0)
    harness.state.set('participant-0', 'third-value')
    assert.deepEqual(await harness.coordinator().recover(), { status: 'recovery_required' }, 'third-value drift fails recovery closed')
    assert.equal(harness.state.get('participant-0'), 'third-value', 'third-value drift is never overwritten')
  }

  {
    const harness = createPortableImportCoordinatorHarness(2)
    await harness.seedPrepared()
    assert.deepEqual(await harness.coordinator().recover(), { status: 'restored' }, 'prepared imports clean up without applying targets')
    assert.deepEqual([...harness.state.values()], ['source-0', 'source-1'], 'prepared recovery leaves sources unchanged')
  }

  {
    const harness = createPortableImportCoordinatorHarness(2)
    await harness.seedCommitted()
    assert.deepEqual(await harness.coordinator().recover(), { status: 'committed' }, 'committed recovery reruns only post-commit invalidation and cleanup')
    assert.deepEqual([...harness.state.values()], ['target-0', 'target-1'], 'committed recovery never rolls imported targets back')
    assert.equal(harness.postCommitCount(), 1, 'committed restart repeats the idempotent post-commit invalidation once')
  }

  {
    const rows = new Map()
    const database = {
      async exec() {},
      async run(source, parameters = []) {
        if (/INSERT OR REPLACE INTO portable_import_recovery_blobs/i.test(source)) {
          rows.set(parameters[0], parameters[1])
        } else if (/DELETE FROM portable_import_recovery_blobs/i.test(source)) {
          rows.delete(parameters[0])
        }
        return { changes: 1, lastInsertRowId: 0 }
      },
      async getFirst(_source, parameters = []) {
        const value = rows.get(parameters[0])
        return value === undefined ? null : { value }
      },
      async getAll() { return [] },
      async transaction(work) { return work(this) },
    }
    const legacy = new Map()
    const blobStorage = createSqlitePortableImportRecoveryBlobStorage({ get: async () => database })
    const store = createAsyncStoragePortableImportRecoveryStore({
      storage: {
        getItem: async (key) => legacy.get(key) ?? null,
        setItem: async (key, value) => { legacy.set(key, value) },
        removeItem: async (key) => { legacy.delete(key) },
      },
      blobStorage,
      digest: async (value) => `sha256:${createHash('sha256').update(value, 'utf8').digest('hex')}`,
    })
    const largeBlob = 'portable-large-backup:'.padEnd(12 * 1024 * 1024, 'x')
    await store.createBlob('large-operation', 'conversations', largeBlob)
    assert.equal(await store.readBlob('large-operation', 'conversations'), largeBlob, 'native recovery blobs preserve a 12 MiB before-image outside AsyncStorage')
    assert.equal(legacy.size, 0, 'large native recovery blobs do not consume the bounded AsyncStorage database')
    await store.removeBlob('large-operation', 'conversations')
    assert.equal(await store.readBlob('large-operation', 'conversations'), undefined, 'large recovery blob cleanup is reread-verified')

    const legacyKey = '@islemind/vnext/portable-import-recovery/blob-v1/legacy-operation/conversations'
    legacy.set(legacyKey, 'legacy-before-image')
    assert.equal(await store.readBlob('legacy-operation', 'conversations'), undefined, 'native recovery no longer reads older AsyncStorage-backed blobs')
    await store.removeBlob('legacy-operation', 'conversations')
    assert.equal(legacy.has(legacyKey), true, 'current blob cleanup does not mutate retired storage')
  }

  {
    const raw = new Map([[PORTABLE_IMPORT_RECOVERY_ENVELOPE_STORAGE_KEY, '{']])
    const store = createAsyncStoragePortableImportRecoveryStore({
      storage: {
        getItem: async (key) => raw.get(key) ?? null,
        setItem: async (key, value) => { raw.set(key, value) },
        removeItem: async (key) => { raw.delete(key) },
      },
      digest: async (value) => `sha256:${createHash('sha256').update(value, 'utf8').digest('hex')}`,
    })
    await assert.rejects(
      () => store.readEnvelope(),
      (error) => error?.code === 'invalid_envelope',
      'malformed durable recovery envelopes fail closed before any participant mutation',
    )
  }
}

function createPortableImportCoordinatorHarness(participantCount) {
  const ids = Array.from({ length: participantCount }, (_, index) => `participant-${index}`)
  const state = new Map(ids.map((id, index) => [id, `source-${index}`]))
  const blobs = new Map()
  const restoreOrder = []
  const restoreSignals = []
  const faults = {
    applyAfter: new Set(),
    afterApply: new Map(),
    restoreFailures: new Map(),
  }
  let envelope
  let postCommitCount = 0

  const digest = async (value) => `sha256:${createHash('sha256').update(value, 'utf8').digest('hex')}`
  const blobKey = (operationId, participantId) => `${operationId}/${participantId}`
  const store = {
    lockScope: 'runtime-only',
    runExclusive: (work) => work(),
    readEnvelope: async () => envelope,
    async writeEnvelope(next, expectedRevision) {
      if ((expectedRevision === null && envelope !== undefined) || (expectedRevision !== null && envelope?.revision !== expectedRevision)) {
        throw new Error('fake envelope conflict')
      }
      envelope = next
    },
    async removeEnvelope(expectedRevision) {
      if (envelope?.revision !== expectedRevision) throw new Error('fake envelope conflict')
      envelope = undefined
    },
    async readBlob(operationId, participantId) {
      return blobs.get(blobKey(operationId, participantId))
    },
    async createBlob(operationId, participantId, value) {
      const key = blobKey(operationId, participantId)
      const existing = blobs.get(key)
      if (existing !== undefined && existing !== value) throw new Error('fake blob conflict')
      blobs.set(key, value)
    },
    async removeBlob(operationId, participantId) {
      blobs.delete(blobKey(operationId, participantId))
    },
    readRaw: async () => null,
    writeRaw: async () => undefined,
    digest,
  }

  const readBackup = async (currentEnvelope, participantId) => {
    const raw = await store.readBlob(currentEnvelope.operationId, participantId)
    const reference = currentEnvelope.preparedBackups.find((backup) => backup.participantId === participantId)
    if (raw === undefined || !reference || await digest(raw) !== reference.digest) throw new Error('missing fake backup')
    return JSON.parse(raw)
  }

  const participants = ids.map((id, index) => ({
    id,
    async prepare(_plan, currentEnvelope) {
      const raw = JSON.stringify({ source: `source-${index}`, target: `target-${index}` })
      await store.createBlob(currentEnvelope.operationId, id, raw)
      return digest(raw)
    },
    async apply(currentEnvelope) {
      const backup = await readBackup(currentEnvelope, id)
      const current = state.get(id)
      if (current !== backup.source && current !== backup.target) throw new Error('fake apply drift')
      state.set(id, backup.target)
      faults.afterApply.get(id)?.()
      if (faults.applyAfter.has(id)) throw new Error('injected late participant failure')
    },
    async restore(currentEnvelope, signal) {
      restoreSignals.push(signal)
      restoreOrder.push(id)
      const remainingFailures = faults.restoreFailures.get(id) ?? 0
      if (remainingFailures > 0) {
        faults.restoreFailures.set(id, remainingFailures - 1)
        throw new Error('injected restore failure')
      }
      const backup = await readBackup(currentEnvelope, id)
      const current = state.get(id)
      if (current !== backup.source && current !== backup.target) throw new Error('fake restore drift')
      state.set(id, backup.source)
    },
    cleanup(currentEnvelope) {
      return store.removeBlob(currentEnvelope.operationId, id)
    },
  }))

  const coordinator = () => createPortableImportRecoveryCoordinator({
    store,
    participants,
    now: () => 100,
    createOperationId: () => 'operation-1',
    sourceText: (plan) => plan.source,
    postCommit: async () => { postCommitCount += 1 },
  })

  async function prepareEnvelope() {
    let next = portableImportRecoveryCore.createPortableImportRecoveryEnvelope({
      operationId: 'operation-1',
      sourceDigest: await digest('seed'),
      participants: ids,
      now: 100,
    })
    await store.writeEnvelope(next, null)
    for (const participant of participants) {
      const backupDigest = await participant.prepare({ source: 'seed' }, next)
      const previous = next
      next = portableImportRecoveryCore.markPortableImportParticipantPrepared(next, participant.id, backupDigest, 100)
      await store.writeEnvelope(next, previous.revision)
    }
    const previous = next
    next = portableImportRecoveryCore.markPortableImportPrepared(next, 100)
    await store.writeEnvelope(next, previous.revision)
    return next
  }

  async function seedPrepared() {
    await prepareEnvelope()
  }

  async function seedApplying(activeIndex) {
    let next = await prepareEnvelope()
    for (let index = 0; index < activeIndex; index += 1) {
      let previous = next
      next = portableImportRecoveryCore.beginPortableImportParticipant(next, index, 100)
      await store.writeEnvelope(next, previous.revision)
      state.set(ids[index], `target-${index}`)
      previous = next
      next = portableImportRecoveryCore.completePortableImportParticipant(next, index, 100)
      await store.writeEnvelope(next, previous.revision)
    }
    const previous = next
    next = portableImportRecoveryCore.beginPortableImportParticipant(next, activeIndex, 100)
    await store.writeEnvelope(next, previous.revision)
    state.set(ids[activeIndex], `target-${activeIndex}`)
  }

  async function seedCommitted() {
    let next = await prepareEnvelope()
    for (let index = 0; index < ids.length; index += 1) {
      let previous = next
      next = portableImportRecoveryCore.beginPortableImportParticipant(next, index, 100)
      await store.writeEnvelope(next, previous.revision)
      state.set(ids[index], `target-${index}`)
      previous = next
      next = portableImportRecoveryCore.completePortableImportParticipant(next, index, 100)
      await store.writeEnvelope(next, previous.revision)
    }
    const previous = next
    next = portableImportRecoveryCore.markPortableImportCommitted(next, 100)
    await store.writeEnvelope(next, previous.revision)
  }

  return {
    coordinator,
    deleteBlob(participantId) {
      blobs.delete(blobKey(envelope.operationId, participantId))
    },
    faults,
    postCommitCount: () => postCommitCount,
    readEnvelope: () => envelope,
    restoreOrder,
    restoreSignals,
    seedApplying,
    seedCommitted,
    seedPrepared,
    state,
  }
}

async function assertSqliteConcurrencySerializationBehavior() {
  resetLocalModelFileMocks()
  resetSqliteConcurrencyProbe()
  const providerA = createExpoSqliteDatabaseProvider({ databaseName: SQLITE_CONCURRENCY_TEST_DATABASE_NAME })
  const providerB = createExpoSqliteDatabaseProvider({ databaseName: SQLITE_CONCURRENCY_TEST_DATABASE_NAME })
  const conversationsA = createSqliteConversationRepository(providerA)
  const conversationsB = createSqliteConversationRepository(providerB)
  const assistantRuns = createSqliteAssistantRunPersistence(providerB)
  const conversation = {
    id: 'sqlite-concurrency-conversation',
    title: 'SQLite concurrency',
    providerId: 'sqlite-test-provider',
    model: 'sqlite-test-model',
    updatedAt: 1,
    messages: [{ id: 'sqlite-concurrency-message', role: 'user', content: 'serialize writes', status: 'done' }],
  }
  const run = {
    id: 'sqlite-concurrency-run',
    kind: 'chat',
    conversationId: conversation.id,
    responseMessageId: 'sqlite-concurrency-response',
    providerId: conversation.providerId,
    model: conversation.model,
    contextSnapshotId: 'sqlite-concurrency-context',
    status: 'queued',
    createdAt: 1,
    journalSequence: 0,
  }

  await Promise.all([providerA.get(), providerB.get()])
  const schemaCountBeforeContention = sqliteConcurrencyProbe.conversationSchemaExecutions
  const pause = pauseNextSqliteConcurrencyTransaction()
  const replacement = conversationsA.replaceAll([conversation])
  await pause.started
  const concurrentSave = conversationsB.save({ ...conversation, updatedAt: 2 })
  const concurrentRun = assistantRuns.appendAndSave({
    schema: 'islemind.assistant-run-journal-entry.v1',
    runId: run.id,
    sequence: 1,
    type: 'run.created',
    occurredAt: 1,
  }, { ...run, journalSequence: 1 })
  pause.release()
  await Promise.all([replacement, concurrentSave, concurrentRun])

  assert.deepEqual(sqliteConcurrencyProbe.lockViolations, [], 'independent SQLite providers never overlap native operations')
  assert.equal(sqliteConcurrencyProbe.maxActiveOperations, 1, 'SQLite operations are serialized per database name')
  assert.equal(sqliteConcurrencyProbe.conversationSchemaExecutions, schemaCountBeforeContention + 2, 'conversation schema initialization runs once per repository')
  assert.equal(sqliteConcurrencyProbe.activeOperations, 0, 'SQLite scheduler releases its operation slot after transactions settle')
  assert.ok(sqliteConcurrencyProbe.operationLog.indexOf('transaction:start') >= 0, 'SQLite concurrency fixture observes the exclusive transaction')
  assert.ok(sqliteConcurrencyProbe.operationLog.indexOf('transaction:end') > sqliteConcurrencyProbe.operationLog.indexOf('transaction:start'), 'SQLite transaction completes before queued writes')

  resetSqliteConcurrencyProbe({ preserveSchemaCount: true })
  await conversationsA.save({ ...conversation, updatedAt: 3 })
  await conversationsA.save({ ...conversation, updatedAt: 4 })
  assert.equal(sqliteConcurrencyProbe.conversationSchemaExecutions, schemaCountBeforeContention + 2, 'repeated repository writes do not reissue conversation-table DDL')

  const retryProvider = createExpoSqliteDatabaseProvider({ databaseName: SQLITE_CONCURRENCY_TEST_DATABASE_NAME })
  sqliteConcurrencyProbe.nextFailure = new Error('transient SQLite open failure')
  await assert.rejects(retryProvider.get(), /transient SQLite open failure/, 'transient native open failure reaches the caller')
  await retryProvider.get()
  assert.equal(sqliteConcurrencyProbe.activeOperations, 0, 'provider retries a transient open failure without poisoning its cached promise')

  resetSqliteConcurrencyProbe({ preserveSchemaCount: true })
  sqliteConcurrencyProbe.nextFailure = new Error('transient queued SQLite failure')
  await assert.rejects(providerA.get().then((database) => database.run('SELECT 1')), /transient queued SQLite failure/)
  await providerB.get().then((database) => database.run('SELECT 1'))
  assert.equal(sqliteConcurrencyProbe.activeOperations, 0, 'database queue continues after a rejected native operation')

  resetSqliteConcurrencyProbe({ preserveSchemaCount: true })
  const schemaCountBeforeRetry = sqliteConcurrencyProbe.conversationSchemaExecutions
  const retryConversations = createSqliteConversationRepository(providerA)
  sqliteConcurrencyProbe.nextFailure = new Error('transient conversation schema failure')
  await assert.rejects(
    retryConversations.save({ ...conversation, updatedAt: 5 }),
    /transient conversation schema failure/,
    'conversation schema initialization failure reaches the caller',
  )
  await retryConversations.save({ ...conversation, updatedAt: 6 })
  await retryConversations.save({ ...conversation, updatedAt: 7 })
  assert.equal(
    sqliteConcurrencyProbe.conversationSchemaExecutions,
    schemaCountBeforeRetry + 1,
    'conversation schema initialization retries once after failure and remains cached after success',
  )

  const previousDocumentDescriptor = Object.getOwnPropertyDescriptor(globalThis, 'document')
  sqliteWebPersistenceProbe.exclusiveTransactions = 0
  sqliteWebPersistenceProbe.transactions = 0
  sqliteWebPersistenceProbe.rows.length = 0
  const openCountBeforeWebPersistence = sqliteOpenRequests.length
  Object.defineProperty(globalThis, 'document', {
    configurable: true,
    value: {},
  })
  try {
    const webProvider = createExpoSqliteDatabaseProvider({ databaseName: SQLITE_WEB_PERSISTENCE_TEST_DATABASE_NAME })
    const webDatabase = await webProvider.get()
    const webTransactionResult = await webDatabase.transaction(async (transaction) => {
      await transaction.exec('CREATE TABLE web_runtime_probe (id TEXT)')
      return transaction.run('INSERT INTO web_runtime_probe (id) VALUES (?)', ['web'])
    })
    assert.deepEqual(
      webTransactionResult,
      { changes: 1, lastInsertRowId: 1 },
      'provider-selected web SQLite commits through the supported transaction contract',
    )
    assert.equal(
      sqliteOpenRequests.length,
      openCountBeforeWebPersistence + 1,
      'provider-selected web SQLite opens the Expo worker-backed database',
    )
    assert.equal(sqliteOpenRequests.at(-1).name, SQLITE_WEB_PERSISTENCE_TEST_DATABASE_NAME)
    assert.equal(sqliteWebPersistenceProbe.transactions, 1, 'web SQLite uses withTransactionAsync')
    assert.equal(sqliteWebPersistenceProbe.exclusiveTransactions, 0, 'web SQLite never calls the unsupported exclusive transaction API')
    assert.deepEqual(
      await webDatabase.getFirst('SELECT id FROM web_runtime_probe WHERE id = ?', ['web']),
      { id: 'web' },
      'web SQLite reads the row written by the transaction',
    )
  } finally {
    if (previousDocumentDescriptor) {
      Object.defineProperty(globalThis, 'document', previousDocumentDescriptor)
    } else {
      delete globalThis.document
    }
  }
}

