function assertProviderModelFamilyBehavior() {
  const providerModels = require('../src/utils/providerModels.ts')
  const relayProvider = {
    id: 'model-family-relay',
    type: 'openai-compatible',
    presetId: 'custom-endpoint', wireProtocol: 'openai-compatible',
    name: 'Custom Model Family Relay',
    baseUrl: 'https://relay.example',
    apiKey: FAKE_KEY_A,
    models: [],
    enabled: true,
  }

  assert.deepEqual(
    providerModels.MODEL_QUICK_GROUPS,
    [
      'all',
      'gpt',
      'claude',
      'gemini',
      'gemma',
      'deepseek',
      'qwen',
      'kimi',
      'doubao',
      'grok',
      'glm',
      'minimax',
      'mistral',
      'llama',
      'command',
      'sonar',
      'hunyuan',
      'ernie',
      'yi',
      'baichuan',
      'stepfun',
      'gpt-oss',
      'mimo',
      'other',
    ],
    'provider model utility owns stable model quick-filter groups'
  )

  for (const [model, family] of WELL_KNOWN_OPENAI_COMPATIBLE_RELAY_MODEL_FAMILIES) {
    assert.equal(
      providerModels.inferModelFamily(relayProvider, model),
      family,
      `provider model utility classifies ${model} as ${family} without changing relay protocol`
    )
  }

  assert.equal(
    providerModels.inferModelFamily({ type: 'anthropic', name: 'Claude', models: [], enabled: true }, 'claude-sonnet-4'),
    'claude',
    'provider model utility classifies Claude-compatible models outside UI components'
  )
  assert.equal(
    providerModels.inferModelFamily({ type: 'openai-compatible', name: 'Xiaomi MiMo', baseUrl: 'https://api.xiaomimimo.com', models: [], enabled: true }, 'mimo-v2'),
    'mimo',
    'provider model utility classifies MiMo-compatible models outside UI components'
  )
  assert.equal(
    providerModels.inferModelFamily({ type: 'openai-compatible', name: 'Perplexity', baseUrl: 'https://api.perplexity.ai', models: [], enabled: true }, 'sonar-pro'),
    'sonar',
    'provider model utility maps Sonar models to the Perplexity/Sonar family'
  )
  assert.equal(
    providerModels.inferModelFamily({ type: 'openai-compatible', name: '01.AI', baseUrl: 'https://api.01.ai/v1', models: [], enabled: true }, undefined),
    'yi',
    'provider model utility falls back to provider identity only for UI family grouping'
  )

  for (const [model] of WELL_KNOWN_OPENAI_COMPATIBLE_RELAY_MODEL_FAMILIES) {
    assert.equal(
      resolveProviderEndpoint({ provider: relayProvider, model, stream: true }),
      'https://relay.example/v1/chat/completions',
      `${model} on a generic OpenAI-compatible relay stays on Chat Completions routing`
    )
    const body = buildOpenAIBodyForTest({
      provider: relayProvider,
      model,
      messages: [{ role: 'user', content: 'Use the relay chat protocol.' }],
      stream: true,
    })
    assert.equal(body.model, model, `${model} OpenAI-compatible body preserves the selected upstream model id`)
    assert.equal(body.messages[0].role, 'user', `${model} OpenAI-compatible body preserves chat messages`)
    assert.equal(body.contents, undefined, `${model} OpenAI-compatible body does not switch to Google generateContent fields`)
    assert.equal(body.system, undefined, `${model} OpenAI-compatible body does not switch to Anthropic messages fields`)
  }

  assert.ok(
    resolveProviderEndpoint({
      provider: { id: 'native-google', type: 'google', name: 'Google', apiKey: FAKE_KEY_A, models: ['gemini-2.5-pro'], enabled: true },
      model: 'gemini-2.5-pro',
      stream: true,
    }).includes('/models/gemini-2.5-pro:streamGenerateContent?alt=sse'),
    'native Google providers still use generateContent routing when provider.type declares Google'
  )
  assert.equal(
    resolveProviderEndpoint({
      provider: { id: 'native-anthropic', type: 'anthropic', name: 'Anthropic', baseUrl: 'https://api.anthropic.com/v1', apiKey: FAKE_KEY_A, models: ['claude-sonnet-4'], enabled: true },
      model: 'claude-sonnet-4',
      stream: true,
    }),
    'https://api.anthropic.com/v1/messages',
    'native Anthropic providers still use Messages routing when provider.type declares Anthropic'
  )

  const providerToolDeclaration = {
    type: 'function',
    function: {
      name: 'inspect_relay_context',
      description: 'Inspect relay-side context.',
      parameters: {
        type: 'object',
        properties: { query: { type: 'string' } },
        required: ['query'],
      },
    },
  }
  const familyOnlyBody = buildOpenAIBodyForTest({
    provider: relayProvider,
    model: 'gpt-oss-120b',
    messages: [{ role: 'user', content: 'Return JSON and use context.' }],
    providerToolDeclarations: [providerToolDeclaration],
    structuredOutput: { type: 'json_schema', name: 'relay_result', schema: { type: 'object' }, strict: true },
    reasoningEffort: 'high',
    attachments: [{ id: 'relay-image', type: 'image', uri: 'file://relay.png', name: 'relay.png', mimeType: 'image/png', size: 10, base64: 'aW1n' }],
    stream: false,
  })
  assert.equal(familyOnlyBody.tools, undefined, 'model-family recognition alone does not enable relay tools')
  assert.equal(familyOnlyBody.response_format, undefined, 'model-family recognition alone does not enable relay structured output')
  assert.equal(familyOnlyBody.reasoning_effort, undefined, 'model-family recognition alone does not enable relay reasoning controls')
  assert.equal(familyOnlyBody.messages[0].content, 'Return JSON and use context.', 'model-family recognition alone does not enable relay vision payloads')
}

async function assertResponsesWebSocketTransportBehavior() {
  const originalWebSocket = global.WebSocket
  try {
    const success = await runFakeWebSocketScenario(({ instance }) => {
      instance.open()
      instance.message({ type: 'response.output_text.delta', delta: 'hel' })
      instance.message({ type: 'response.output_text.delta', delta: 'lo' })
      instance.message({ type: 'response.completed', response: { id: 'resp-ok' }, usage: { input_tokens: 30, output_tokens: 2, total_tokens: 32 } })
    })
    assert.deepEqual(success.chunks, ['hel', 'lo'], 'Responses WebSocket emits streamed text chunks')
    assert.equal(success.done?.text, 'hello', 'Responses WebSocket completes with accumulated text')
    assert.equal(success.done?.responseId, 'resp-ok', 'Responses WebSocket forwards response id')
    assert.equal(success.done?.usage?.inputTokens, 30, 'Responses WebSocket forwards provider usage')
    assert.ok(success.sent.some((message) => message.type === 'response.create'), 'Responses WebSocket sends response.create')
    assert.ok(!('stream' in success.sent[0]), 'Responses WebSocket removes stream from response.create payload')

    const toolCallSuccess = await runFakeWebSocketScenario(({ instance }) => {
      instance.open()
      instance.message({ type: 'response.output_item.added', item: { id: 'rs_websocket_search', type: 'reasoning', encrypted_content: 'encrypted-websocket-reasoning', summary: [] } })
      instance.message({ type: 'response.output_item.added', item: { id: 'fc_websocket_search', call_id: 'call_websocket_search', type: 'function_call', name: 'search_web', arguments: '{"query":' } })
      instance.message({ type: 'response.function_call_arguments.delta', item_id: 'fc_websocket_search', delta: '"Isle' })
      instance.message({ type: 'response.function_call_arguments.delta', item_id: 'fc_websocket_search', delta: 'Mind"}' })
      instance.message({ type: 'response.completed', response: { id: 'resp-tool-ok' } })
    })
    assert.equal(toolCallSuccess.done?.providerToolCalls?.[0]?.id, 'fc_websocket_search', 'Responses WebSocket forwards provider tool call id')
    assert.equal(toolCallSuccess.done?.providerToolCalls?.[0]?.callId, 'call_websocket_search', 'Responses WebSocket forwards provider function call_id')
    assert.equal(toolCallSuccess.done?.providerToolCalls?.[0]?.name, 'search_web', 'Responses WebSocket forwards provider tool call name')
    assert.equal(toolCallSuccess.done?.providerToolCalls?.[0]?.arguments?.query, 'IsleMind', 'Responses WebSocket merges streamed provider tool arguments')
    assert.deepEqual(
      toolCallSuccess.done?.responseItems?.[0],
      { id: 'rs_websocket_search', type: 'reasoning', encrypted_content: 'encrypted-websocket-reasoning', summary: [] },
      'Responses WebSocket forwards reasoning replay items'
    )

    const textToolCallSuccess = await runFakeWebSocketScenario(({ instance }) => {
      instance.open()
      instance.message({ type: 'response.output_text.delta', delta: '我需要搜索。\n<tool_call>\n' })
      instance.message({ type: 'response.output_text.delta', delta: '<function=search_web>\n<parameter=query>嘉年华 西瓜 品种介绍</parameter>\n' })
      instance.message({ type: 'response.output_text.delta', delta: '<parameter=limit>5</parameter>\n</function>\n</tool_call>' })
      instance.message({ type: 'response.completed', response: { id: 'resp-text-tool-ok' } })
    })
    assert.deepEqual(textToolCallSuccess.chunks, ['我需要搜索。\n'], 'Responses WebSocket hides XML-style text tool-call chunks from the visible stream')
    assert.equal(textToolCallSuccess.done?.text, '我需要搜索。', 'Responses WebSocket strips XML-style text tool-call blocks before completion')
    assert.equal(textToolCallSuccess.done?.providerToolCalls?.[0]?.name, 'search_web', 'Responses WebSocket recovers XML-style text tool-call names')
    assert.equal(textToolCallSuccess.done?.providerToolCalls?.[0]?.arguments?.query, '嘉年华 西瓜 品种介绍', 'Responses WebSocket recovers XML-style text tool-call query')
    assert.equal(textToolCallSuccess.done?.providerToolCalls?.[0]?.arguments?.limit, 5, 'Responses WebSocket coerces XML-style numeric text tool-call parameters')

    const handshakeFailure = await runFakeWebSocketScenario(({ instance }) => {
      instance.error()
    })
    assert.equal(handshakeFailure.error?.message, 'websocket_transport_error', 'Responses WebSocket rejects handshake failure before tokens')
    assert.equal(handshakeFailure.chunks.length, 0, 'Responses WebSocket handshake failure emits no chunks')

    const midStreamFailure = await runFakeWebSocketScenario(({ instance }) => {
      instance.open()
      instance.message({ type: 'response.output_text.delta', delta: 'partial' })
      instance.error()
    })
    assert.equal(midStreamFailure.error?.message, 'websocket_transport_error', 'Responses WebSocket rejects mid-stream failure')
    assert.deepEqual(midStreamFailure.chunks, ['partial'], 'Responses WebSocket mid-stream failure preserves emitted chunks for caller retry policy')

    const abortController = new AbortController()
    const aborted = await runFakeWebSocketScenario(({ instance }) => {
      instance.open()
      abortController.abort()
    }, abortController)
    assert.equal(aborted.error?.name, 'AbortError', 'Responses WebSocket abort rejects with AbortError')
    assert.equal(aborted.closed, true, 'Responses WebSocket abort closes the socket')

    const exactAbortReason = { code: 'cancel-websocket-transport' }
    const exactAbortController = new AbortController()
    const exactAborted = await runFakeWebSocketScenario(({ instance }) => {
      instance.open()
      exactAbortController.abort(exactAbortReason)
      instance.message({ type: 'response.output_text.delta', delta: 'late' })
      instance.message({ type: 'response.completed', response: { id: 'late-response' } })
    }, exactAbortController)
    assert.equal(exactAborted.error, exactAbortReason, 'Responses WebSocket preserves an arbitrary cancellation reason by identity')
    assert.deepEqual(exactAborted.chunks, [], 'Responses WebSocket emits no late chunks after cancellation')
    assert.equal(exactAborted.done, null, 'Responses WebSocket emits no late completion after cancellation')

    const preAbortReason = { code: 'cancel-websocket-before-start' }
    const preAbortController = new AbortController()
    preAbortController.abort(preAbortReason)
    const preAborted = await runFakeWebSocketScenario(() => {
      throw new Error('pre-aborted Responses WebSocket created a transport instance')
    }, preAbortController)
    assert.equal(preAborted.error, preAbortReason, 'pre-aborted Responses WebSocket preserves the exact cancellation reason')
    assert.equal(preAborted.instanceCount, 0, 'pre-aborted Responses WebSocket creates no socket')

    const reentrantController = new AbortController()
    const reentrantCompletion = await runFakeWebSocketScenario(({ instance }) => {
      instance.open()
      instance.message({ type: 'response.output_text.delta', delta: 'complete' })
      instance.message({ type: 'response.completed', response: { id: 'reentrant-completion' } })
    }, reentrantController, {
      onDone() {
        reentrantController.abort({ code: 'abort-from-on-done' })
      },
    })
    assert.equal(reentrantCompletion.done?.text, 'complete', 'Responses WebSocket preserves completion when onDone aborts reentrantly')
    assert.equal(reentrantCompletion.error, null, 'Responses WebSocket resolves after a reentrant onDone abort')
    assert.equal(reentrantCompletion.doneCalls, 1, 'Responses WebSocket invokes onDone once under reentrant cancellation')

    const key = 'provider:model:conversation:session'
    const lease = await acquireProviderSessionLease({ key, limit: 1, timeoutMs: 10 })
    assert.equal(activeProviderSessionLeaseCount(key), 1, 'session lease records active acquisition')
    lease.release()
    lease.release()
    assert.equal(activeProviderSessionLeaseCount(key), 0, 'session lease release is idempotent')

    const firstPool = createProviderSessionLeasePool()
    const secondPool = createProviderSessionLeasePool()
    const isolatedLease = await firstPool.acquire({ key, limit: 1, timeoutMs: 10 })
    assert.equal(firstPool.activeCount(key), 1, 'session lease pools track their own acquisitions')
    assert.equal(secondPool.activeCount(key), 0, 'session lease pool instances do not share hidden global state')
    await assert.rejects(
      firstPool.acquire({ key, limit: 1, timeoutMs: 0 }),
      /session_queue_timeout/,
      'occupied session lease pools preserve immediate timeout behavior',
    )

    const queuedAbortController = new AbortController()
    const queuedLease = firstPool.acquire({
      key,
      limit: 1,
      timeoutMs: 1000,
      signal: queuedAbortController.signal,
    })
    queuedAbortController.abort()
    await assert.rejects(queuedLease, (error) => error?.name === 'AbortError', 'queued session lease cancellation propagates AbortError')
    assert.equal(firstPool.activeCount(key), 1, 'cancelled queued acquisition does not consume a lease')
    isolatedLease.release()
    assert.equal(firstPool.activeCount(key), 0, 'isolated session lease release clears the pool')
  } finally {
    if (originalWebSocket === undefined) {
      delete global.WebSocket
    } else {
      global.WebSocket = originalWebSocket
    }
  }
}

async function assertProviderTextToolCallFallbackBehavior() {
  const xmlStyleTextToolCall = [
    '我需要搜索。',
    '<tool_call>',
    '<function=search_web>',
    '<parameter=query>嘉年华 西瓜 品种介绍</parameter>',
    '<parameter=limit>5</parameter>',
    '</function>',
    '</tool_call>',
  ].join('\n')
  assert.deepEqual(
    extractProviderTextToolCalls(xmlStyleTextToolCall)?.[0],
    {
      id: 'text-tool-call-0-0',
      callId: 'text-tool-call-0-0',
      index: 0,
      name: 'search_web',
      arguments: { query: '嘉年华 西瓜 品种介绍', limit: 5 },
      rawArguments: '{"query":"嘉年华 西瓜 品种介绍","limit":5}',
      argumentsComplete: true,
    },
    'provider text tool-call helper recovers XML-style search_web calls'
  )
  assert.equal(
    stripProviderTextToolCallBlocks(xmlStyleTextToolCall).trim(),
    '我需要搜索。',
    'provider text tool-call helper strips XML-style blocks from visible text'
  )
  const nonStreamingTextToolResult = await parseProviderNonStreamingResponse(new Response(xmlStyleTextToolCall), {
    provider: { id: 'text-tool-provider', type: 'openai-compatible', name: 'Text Tool Provider', apiKey: FAKE_KEY_A, models: [], enabled: true, capabilities: { nativeTools: true } },
    model: 'gpt-5.5',
    messages: [],
  })
  assert.equal(nonStreamingTextToolResult.text, '我需要搜索。', 'provider response parsing helper removes XML-style text tool-call blocks from plain responses')
  assert.equal(nonStreamingTextToolResult.providerToolCalls?.[0]?.name, 'search_web', 'provider response parsing helper recovers XML-style text tool calls from plain responses')
  assert.equal(nonStreamingTextToolResult.providerToolCalls?.[0]?.arguments?.limit, 5, 'provider response parsing helper keeps XML-style numeric arguments executable')
  const bufferedSseTextToolResult = parseProviderBufferedStreamResponse(`data: ${JSON.stringify({ type: 'response.output_text.delta', delta: xmlStyleTextToolCall })}`, {
    provider: { id: 'buffered-text-tool-provider', type: 'openai', name: 'Buffered Text Tool Provider', apiKey: FAKE_KEY_A, models: [], enabled: true },
    model: 'gpt-5.5',
    messages: [],
  }, 'openai')
  assert.equal(bufferedSseTextToolResult.text, '我需要搜索。', 'provider response parsing helper strips XML-style text tool-call blocks from buffered streams')
  assert.equal(bufferedSseTextToolResult.providerToolCalls?.[0]?.arguments?.query, '嘉年华 西瓜 品种介绍', 'provider response parsing helper recovers XML-style buffered stream tool calls')
  const openAITextToolParsedCompletion = parseProviderChatCompletionJson({
    id: 'resp_text_tool_parse',
    output_text: xmlStyleTextToolCall,
  }, {
    provider: { id: 'openai-text-tool-parse', type: 'openai', name: 'OpenAI Text Tool Parse', apiKey: FAKE_KEY_A, models: [], enabled: true },
    model: 'gpt-5.5',
    messages: [],
  })
  assert.equal(openAITextToolParsedCompletion.text, '我需要搜索。', 'provider response parsing helper strips XML-style text tool-call blocks from JSON completions')
  assert.equal(openAITextToolParsedCompletion.providerToolCalls?.[0]?.name, 'search_web', 'provider response parsing helper recovers XML-style text tool calls from JSON completions')
}

async function runFakeWebSocketScenario(script, controller = new AbortController(), hooks = {}) {
  const instances = []
  class FakeWebSocket {
    constructor(url, _protocols, options) {
      this.url = url
      this.options = options
      this.sent = []
      this.closed = false
      instances.push(this)
    }
    send(value) {
      this.sent.push(JSON.parse(value))
    }
    close() {
      this.closed = true
    }
    open() {
      this.onopen?.()
    }
    message(payload) {
      this.onmessage?.({ data: JSON.stringify(payload) })
    }
    error() {
      this.onerror?.(new Error('fake websocket error'))
    }
  }
  global.WebSocket = FakeWebSocket
  const chunks = []
  const traces = []
  let done = null
  let doneCalls = 0
  let error = null
  const promise = responsesWebSocketTransport.run({
    url: 'wss://api.example/v1/responses',
    headers: { Authorization: 'Bearer sk-test-token' },
    body: { model: 'gpt-5.2', input: [{ role: 'user', content: 'hello' }], stream: true },
    req: { provider: { id: 'openai-main', type: 'openai', name: 'OpenAI', apiKey: '', models: ['gpt-5.2'], enabled: true }, model: 'gpt-5.2', messages: [{ role: 'user', content: 'hello' }] },
    signal: controller.signal,
    parseEvent: parseProviderStreamEventForTest,
    wireProviderType: 'openai',
    extractCitations: () => [],
    onChunk: (chunk) => chunks.push(chunk),
    onDone: (result) => {
      done = result
      doneCalls += 1
      hooks.onDone?.(result)
    },
    onError: (err) => { error = err },
    onTrace: (trace) => traces.push(trace),
  }).catch((err) => { error = err })
  if (!controller.signal.aborted) {
    assert.equal(instances.length, 1, 'fake WebSocket instance was created')
    script({ instance: instances[0] })
  }
  await promise
  return {
    chunks,
    traces,
    done,
    error,
    sent: instances[0]?.sent ?? [],
    closed: instances[0]?.closed ?? false,
    instanceCount: instances.length,
    doneCalls,
  }
}

async function assertRuntimeLogFileBehavior() {
  const uri = getRuntimeLogPath()
  localFileFixtures.delete(uri)
  await appendRuntimeLog('upstream.request', {
    providerId: 'openai-main',
    model: 'gpt-5.2',
    authorization: 'Bearer abcdefghijklmnopqrstuvwxyz123456',
    route: {
      endpoint: `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash:streamGenerateContent?alt=sse&key=${FAKE_KEY_A}`,
      fallback: 'https://proxy.example/chat?token=runtime-token-secret',
    },
    headerText: 'Authorization: Basic QWxhZGRpbjpvcGVuIHNlc2FtZQ==; proxy-authorization: bearer abcdefghijklmnopqrstuvwxyz123456',
    body: JSON.stringify({ model: 'gpt-5.2', input: [{ content: 'secret prompt text' }] }),
  }, { enabled: true, maxBytes: 4096 })
  const content = localFileFixtures.get(uri)?.toString('utf8') ?? ''
  const entry = JSON.parse(content.trim())
  assert.equal(entry.schema, 'islemind.runtime-log.v1', 'runtime log writes JSONL schema')
  assert.equal(entry.event, 'upstream.request', 'runtime log writes event family')
  assert.equal(entry.authorization, '[redacted]', 'runtime log file redacts authorization')
  assert.equal(entry.route.endpoint, 'https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash:streamGenerateContent?alt=sse&key=[redacted]', 'runtime log file redacts sensitive query-string API keys')
  assert.equal(entry.route.fallback, 'https://proxy.example/chat?token=[redacted]', 'runtime log file redacts sensitive query-string token parameters')
  assert.equal(entry.headerText, 'Authorization: Basic [redacted]; proxy-authorization: bearer [redacted]', 'runtime log file redacts header-like authorization strings')
  assert.deepEqual(entry.body.keys, ['input', 'model'], 'runtime log file stores payload keys only')
  assert.ok(!content.includes('secret prompt text'), 'runtime log file omits raw prompt text')
  assert.ok(!content.includes(FAKE_KEY_A), 'runtime log file omits raw query-string API key values')
  await appendRuntimeLog('provider.compatibility', {
    providerId: 'bedrock',
    model: 'anthropic.claude-3-5-sonnet',
    compatibilityId: 'aws-bedrock',
    auditState: 'needs-live-smoke',
    liveSmokeRequiredEnv: ['AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY'],
    secret: 'AKIDEXAMPLE',
  }, { enabled: true, maxBytes: 4096 })
  const compatibilityEntry = (localFileFixtures.get(uri)?.toString('utf8') ?? '')
    .trim()
    .split('\n')
    .filter(Boolean)
    .map((line) => JSON.parse(line))
    .find((item) => item.event === 'provider.compatibility')
  assert.equal(compatibilityEntry.compatibilityId, 'aws-bedrock', 'runtime log file writes provider compatibility event family')
  assert.equal(compatibilityEntry.secret, '[redacted]', 'runtime log file redacts provider compatibility secret fields')
  const runtimeEventEnvelope = buildRuntimeEventEnvelope({
    event: 'provider.route.decided',
    conversationId: 'conversation-runtime-event',
    providerId: 'openai-main',
    model: 'gpt-5.2',
    data: {
      authorization: 'Bearer runtime-event-secret-abcdefghijklmnopqrstuvwxyz',
      body: JSON.stringify({ model: 'gpt-5.2', input: 'runtime event prompt text' }),
      nested: { apiKey: FAKE_KEY_A },
    },
  }, new Date('2026-01-02T03:04:05.000Z'))
  assert.equal(runtimeEventEnvelope.schema, 'islemind.runtime-event.v1', 'runtime event envelope writes control-plane schema')
  assert.equal(runtimeEventEnvelope.ts, '2026-01-02T03:04:05.000Z', 'runtime event envelope uses caller timestamp')
  assert.equal(runtimeEventEnvelope.data.authorization, '[redacted]', 'runtime event envelope redacts authorization')
  assert.deepEqual(runtimeEventEnvelope.data.body.keys, ['input', 'model'], 'runtime event envelope stores payload keys only')
  assert.equal(runtimeEventEnvelope.data.nested.apiKey, '[redacted]', 'runtime event envelope redacts nested credential fields')
  assert.equal(runtimeLogEventForRuntimeEvent('provider.route.decided'), 'route.decision', 'runtime event maps to legacy route decision event')
  assert.equal(runtimeLogEventForRuntimeEvent('provider.access.decided'), 'access.policy', 'runtime event maps access policy decisions to legacy logs')
  assert.equal(runtimeLogEventForRuntimeEvent('provider.route.snapshot.created'), 'route.snapshot', 'runtime event maps route snapshots to the legacy snapshot event')
  assert.equal(runtimeLogEventForRuntimeEvent('provider.proxy.decided'), 'proxy.policy', 'runtime event maps proxy decisions to legacy logs')
  assert.equal(runtimeLogEventForRuntimeEvent('provider.fallback.decided'), 'fallback.decision', 'runtime event maps fallback decisions to legacy logs')
  assert.equal(runtimeLogEventForRuntimeEvent('session.affinity.resolved'), 'session.affinity', 'runtime event maps session affinity resolution to the legacy affinity event')
  assert.equal(runtimeLogEventForRuntimeEvent('session.affinity.bound'), 'session.affinity', 'runtime event maps session affinity binding to the legacy affinity event')
  assert.equal(runtimeLogEventForRuntimeEvent('session.affinity.invalidated'), 'session.affinity', 'runtime event maps session affinity invalidation to the legacy affinity event')
  assert.equal(runtimeLogEventForRuntimeEvent('session.affinity.rotated'), 'session.affinity', 'runtime event maps session affinity rotation to the legacy affinity event')
  assert.equal(runtimeLogEventForRuntimeEvent('session.lease.acquired'), 'session.lease', 'runtime event maps session lease acquisition to legacy logs')
  assert.equal(runtimeLogEventForRuntimeEvent('session.lease.rejected'), 'session.lease', 'runtime event maps session lease rejection to legacy logs')
  assert.equal(runtimeLogEventForRuntimeEvent('context.planned'), 'context.operation', 'runtime event maps context planning to context operation logs')
  assert.equal(runtimeLogEventForRuntimeEvent('context.fragment.included'), 'context.operation', 'runtime event maps included context fragments to context operation logs')
  assert.equal(runtimeLogEventForRuntimeEvent('context.fragment.excluded'), 'context.operation', 'runtime event maps excluded context fragments to context operation logs')
  assert.equal(runtimeLogEventForRuntimeEvent('tool.mcp.compatibility.checked'), 'context.operation', 'MCP compatibility summaries map to context operation logs')
  assert.equal(runtimeLogEventForRuntimeEvent('agent.security.evaluation.checked'), 'context.operation', 'agent security summaries map to context operation logs')
  assert.equal(runtimeLogEventForRuntimeEvent('plugin.catalog.snapshot.created'), 'context.operation', 'plugin catalog snapshots map to context operation logs')
  assert.equal(runtimeLogEventForRuntimeEvent('runtime.repair.replay.submitted'), 'context.operation', 'runtime repair replay submit actions map to context operation logs')
  assert.equal(runtimeLogEventForRuntimeEvent('runtime.repair.replay.applied'), 'context.operation', 'runtime repair replay draft actions map to context operation logs')
  assert.equal(runtimeLogEventForRuntimeEvent('runtime.repair.replay.dismissed'), 'context.operation', 'runtime repair replay dismiss actions map to context operation logs')
  assert.equal(runtimeLogEventForRuntimeEvent('context.compact.decided'), 'compact.request', 'runtime event maps context compact decisions to compact request logs')
  assert.equal(runtimeLogEventForRuntimeEvent('context.compact.completed'), 'compact.usage', 'runtime event maps compact usage to legacy compact usage logs')
  const providerRuntimePipelineSource = fs.readFileSync(path.join(root, 'src/bootstrap/providerRuntimePipeline.ts'), 'utf8')
  assert.ok(providerRuntimePipelineSource.includes("event: 'provider.access.decided'"), 'provider runtime pipeline emits typed access decision events')
  assert.ok(providerRuntimePipelineSource.includes("event: 'provider.route.snapshot.created'"), 'provider runtime pipeline emits typed route snapshot events')
  assert.ok(!providerRuntimePipelineSource.includes("appendRuntimeLog('access.policy'"), 'provider runtime pipeline does not write access decisions outside runtime events')
  const providerRuntimeDiagnosticsSource = fs.readFileSync(path.join(root, 'src/bootstrap/providerRuntimeDiagnostics.ts'), 'utf8')
  assert.ok(providerRuntimeDiagnosticsSource.includes("event: 'provider.route.decided'"), 'provider route diagnostics emits typed route decision events')
  assert.ok(providerRuntimeDiagnosticsSource.includes("event: 'provider.proxy.decided'"), 'provider route diagnostics emits typed proxy decision events')
  assert.ok(!providerRuntimeDiagnosticsSource.includes("appendRuntimeLog('proxy.policy'"), 'provider proxy decisions do not bypass runtime events')
  const providerRuntimeFallbackEffectsSource = fs.readFileSync(path.join(root, 'src/bootstrap/providerRuntimeFallbackEffects.ts'), 'utf8')
  assert.ok(providerRuntimeFallbackEffectsSource.includes("event: 'provider.fallback.decided'"), 'runtime fallback decisions emit typed runtime events')
  assert.ok(!providerRuntimeFallbackEffectsSource.includes("appendRuntimeLog('fallback.decision'"), 'runtime fallback decisions do not bypass runtime events')
  assert.equal(fs.existsSync(path.join(root, 'src/services/ai/providerRuntimeFallbackLogging.ts')), false, 'legacy runtime fallback logging helper stays deleted after bootstrap composition')
  const providerRuntimeExecutorSourceForEvents = fs.readFileSync(path.join(root, 'src/bootstrap/providerRuntimeExecutor.ts'), 'utf8')
  assert.ok(providerRuntimeExecutorSourceForEvents.includes("event: 'session.lease.acquired'"), 'runtime executor emits typed session lease acquisition events')
  assert.ok(providerRuntimeExecutorSourceForEvents.includes("event: 'session.lease.rejected'"), 'runtime executor emits typed session lease rejection events')
  assert.ok(providerRuntimeExecutorSourceForEvents.includes("event: 'context.compact.completed'"), 'runtime executor emits typed compact usage events for fallback paths')
  assert.ok(!providerRuntimeExecutorSourceForEvents.includes("appendRuntimeLog('session.lease'"), 'runtime executor does not write session lease logs outside runtime events')
  const requestPlanningRuntimeEventSource = fs.readFileSync(path.join(root, 'src/modules/assistant-runtime/application/assistantConversationRequestPlanningRuntime.ts'), 'utf8')
  const providerRemoteCompactLifecycleSource = fs.readFileSync(path.join(root, 'src/modules/providers/providerRemoteCompactLifecycle.ts'), 'utf8')
  const providerRemoteCompactLifecycleBootstrapSource = fs.readFileSync(path.join(root, 'src/bootstrap/providerRemoteCompactLifecycle.ts'), 'utf8')
  assert.ok(requestPlanningRuntimeEventSource.includes("event: 'context.compact.decided'"), 'Assistant Runtime emits typed compact request events')
  assert.ok(requestPlanningRuntimeEventSource.includes("event: 'context.compact.completed'"), 'Assistant Runtime emits typed compact usage events')
  assert.ok(providerRemoteCompactLifecycleSource.includes("event: 'context.compact.decided'"), 'provider lifecycle emits typed compact state-reuse events')
  assert.ok(providerRemoteCompactLifecycleSource.includes("event: 'context.compact.completed'"), 'provider lifecycle emits typed compact outcome events')
  assert.ok(providerRemoteCompactLifecycleBootstrapSource.includes('createProviderRemoteCompactLifecycle({'), 'bootstrap composes the provider remote-compact lifecycle')
  assert.ok(!requestPlanningRuntimeEventSource.includes("appendRuntimeLog('compact.request'"), 'Assistant Runtime does not write compact request logs outside runtime events')
  assert.ok(!requestPlanningRuntimeEventSource.includes("appendRuntimeLog('compact.usage'"), 'Assistant Runtime does not write compact usage logs outside runtime events')
  await emitRuntimeEvent({
    event: 'provider.route.decided',
    conversationId: 'conversation-runtime-event',
    providerId: 'openai-main',
    model: 'gpt-5.2',
    legacyData: {
      schema: 'bad-schema',
      ts: 'bad-ts',
      event: 'upstream.error',
      runtimeEvent: { event: 'bad-event' },
      providerId: 'openai-main',
      model: 'gpt-5.2',
      route: { protocol: 'openai-compatible', blocked: false },
    },
    data: {
      requestedModel: 'gpt-5.2',
      authorization: 'Bearer emitted-runtime-event-secret-abcdefghijklmnopqrstuvwxyz',
      body: JSON.stringify({ model: 'gpt-5.2', input: 'emitted runtime event prompt text' }),
    },
    options: { enabled: true, maxBytes: 4096 },
  })
  const runtimeEventContent = localFileFixtures.get(uri)?.toString('utf8') ?? ''
  const runtimeLogEntry = runtimeEventContent
    .trim()
    .split('\n')
    .filter(Boolean)
    .map((line) => JSON.parse(line))
    .find((item) => item.event === 'route.decision' && item.runtimeEvent?.event === 'provider.route.decided')
  assert.ok(runtimeLogEntry, 'runtime event emit writes route decision entry')
  assert.equal(runtimeLogEntry.schema, 'islemind.runtime-log.v1', 'runtime event emit preserves legacy runtime log schema')
  assert.equal(runtimeLogEntry.event, 'route.decision', 'runtime event emit preserves legacy runtime log event family')
  assert.ok(runtimeLogEntry.ts !== 'bad-ts', 'runtime event emit ignores legacy timestamp override')
  assert.equal(runtimeLogEntry.providerId, 'openai-main', 'runtime event emit preserves legacy provider id')
  assert.equal(runtimeLogEntry.runtimeEvent.schema, 'islemind.runtime-event.v1', 'runtime event emit embeds typed envelope')
  assert.equal(runtimeLogEntry.runtimeEvent.conversationId, 'conversation-runtime-event', 'runtime event emit embeds conversation id')
  assert.equal(runtimeLogEntry.runtimeEvent.providerId, 'openai-main', 'runtime event emit embeds provider id')
  assert.equal(runtimeLogEntry.runtimeEvent.model, 'gpt-5.2', 'runtime event emit embeds model')
  assert.equal(runtimeLogEntry.runtimeEvent.data.authorization, '[redacted]', 'runtime event emit redacts envelope authorization')
  assert.deepEqual(runtimeLogEntry.runtimeEvent.data.body.keys, ['input', 'model'], 'runtime event emit stores envelope payload keys only')
  assert.ok(!runtimeEventContent.includes('emitted runtime event prompt text'), 'runtime event emit omits raw prompt text')
  assert.ok(!runtimeEventContent.includes('emitted-runtime-event-secret'), 'runtime event emit omits raw credential text')
  await emitRuntimeEvent({
    event: 'provider.route.snapshot.created',
    conversationId: 'conversation-runtime-event',
    providerId: 'openai-main',
    credentialGroupId: 'group-a',
    model: 'gpt-5.2',
    data: {
      snapshot: {
        schema: 'islemind.provider-route-decision-snapshot.v1',
        id: 'snapshot-runtime-log',
        providerId: 'openai-main',
        credentialGroupId: 'group-a',
        requestPolicy: { requestFieldKeys: ['model', 'messages'], findingIds: [] },
      },
    },
    legacyData: {
      providerId: 'openai-main',
      model: 'gpt-5.2',
      credentialGroupId: 'group-a',
      routeDecisionSnapshot: { id: 'snapshot-runtime-log' },
    },
    options: { enabled: true, maxBytes: 4096 },
  })
  const routeSnapshotEntry = (localFileFixtures.get(uri)?.toString('utf8') ?? '')
    .trim()
    .split('\n')
    .filter(Boolean)
    .map((line) => JSON.parse(line))
    .find((item) => item.event === 'route.snapshot' && item.runtimeEvent?.event === 'provider.route.snapshot.created')
  assert.ok(routeSnapshotEntry, 'runtime event emit writes route snapshot entries')
  assert.equal(routeSnapshotEntry.runtimeEvent.credentialGroupId, 'group-a', 'runtime route snapshot event embeds credential group id')
  const boundedEventEnvelope = buildRuntimeEventEnvelope({
    event: 'provider.route.decided',
    data: {
      items: Array.from({ length: RUNTIME_EVENT_DATA_LIST_LIMIT + 8 }, (_, index) => ({ index })),
      object: Object.fromEntries(Array.from({ length: RUNTIME_EVENT_DATA_OBJECT_FIELD_LIMIT + 8 }, (_, index) => [`field${index}`, index])),
    },
  }, new Date('2026-01-02T03:04:06.000Z'))
  assert.equal(boundedEventEnvelope.data.items.length, RUNTIME_EVENT_DATA_LIST_LIMIT, 'runtime event envelope caps list data for bounded history')
  assert.equal(Object.keys(boundedEventEnvelope.data.object).length, RUNTIME_EVENT_DATA_OBJECT_FIELD_LIMIT, 'runtime event envelope caps object fields for bounded history')
  const beforeTokenUsageEventContent = localFileFixtures.get(uri)?.toString('utf8') ?? ''
  assert.equal(shouldPersistRuntimeEvent('token_usage.updated'), false, 'runtime events skip high-frequency token usage writes by default')
  clearRuntimeEventHistoryForTest()
  const observedRuntimeEvents = []
  const unsubscribeRuntimeEvents = subscribeRuntimeEvents((event) => observedRuntimeEvents.push(event))
  const throwingUnsubscribe = subscribeRuntimeEvents(() => {
    throw new Error('subscriber failure must be isolated')
  })
  const tokenUsageEnvelope = await emitRuntimeEvent({
    event: 'token_usage.updated',
    conversationId: 'conversation-runtime-event',
    providerId: 'openai-main',
    model: 'gpt-5.2',
    data: { outputTokens: 1, totalTokens: 2 },
    options: { enabled: true, maxBytes: 4096 },
  })
  assert.equal(tokenUsageEnvelope.event, 'token_usage.updated', 'high-frequency runtime events still build typed envelopes')
  assert.equal(localFileFixtures.get(uri)?.toString('utf8') ?? '', beforeTokenUsageEventContent, 'high-frequency token usage events do not append runtime log lines')
  assert.equal(shouldNotifyRuntimeEventSubscribers('token_usage.updated'), false, 'runtime events skip high-frequency subscriber notifications by default')
  assert.equal(observedRuntimeEvents.length, 0, 'high-frequency token usage events do not notify subscribers per token')
  assert.equal(getRuntimeEventHistory()[0].id, tokenUsageEnvelope.id, 'runtime event history records skipped-log high-frequency events')
  const routeEventEnvelope = await emitRuntimeEvent({
    event: 'provider.route.decided',
    conversationId: 'conversation-runtime-event',
    providerId: 'openai-main',
    model: 'gpt-5.2',
    data: { blocked: false },
    options: { enabled: false },
  })
  assert.equal(observedRuntimeEvents.length, 1, 'runtime event subscribers receive low-frequency emitted envelopes')
  assert.equal(observedRuntimeEvents[0].id, routeEventEnvelope.id, 'runtime event subscribers receive the exact low-frequency envelope')
  unsubscribeRuntimeEvents()
  throwingUnsubscribe()
  await emitRuntimeEvent({
    event: 'provider.route.decided',
    conversationId: 'conversation-runtime-event',
    providerId: 'openai-main',
    model: 'gpt-5.2',
    data: { blocked: false },
    options: { enabled: false },
  })
  assert.equal(observedRuntimeEvents.length, 1, 'runtime event unsubscribe stops future notifications')
  clearRuntimeEventHistoryForTest()
  for (let index = 0; index < RUNTIME_EVENT_HISTORY_LIMIT + 5; index += 1) {
    await emitRuntimeEvent({
      event: 'token_usage.updated',
      conversationId: `history-${index}`,
      data: { index },
      options: { enabled: true, maxBytes: 4096 },
    })
  }
  const boundedHistory = getRuntimeEventHistory(RUNTIME_EVENT_HISTORY_LIMIT + 10)
  assert.equal(boundedHistory.length, RUNTIME_EVENT_HISTORY_LIMIT, 'runtime event history stays size-limited')
  assert.equal(boundedHistory[0].conversationId, 'history-5', 'runtime event history evicts oldest entries beyond the cap')
  assert.equal(getRuntimeEventHistory(3).length, 3, 'runtime event history supports bounded reads')
  assert.equal(getRuntimeEventHistory(0).length, 0, 'runtime event history supports explicit empty reads')
  assert.equal(getRuntimeEventHistory(-1).length, 0, 'runtime event history treats negative read limits as empty')
  clearRuntimeEventHistoryForTest()
  await emitRuntimeEvent({
    event: 'provider.route.decided',
    conversationId: 'history-explanatory-route',
    data: { blocked: false },
    options: { enabled: false },
  })
  for (let index = 0; index < RUNTIME_EVENT_HISTORY_LIMIT + 5; index += 1) {
    await emitRuntimeEvent({
      event: 'token_usage.updated',
      conversationId: `history-token-${index}`,
      data: { index },
      options: { enabled: true, maxBytes: 4096 },
    })
  }
  const explanatoryHistory = getRuntimeEventHistory()
  assert.equal(explanatoryHistory.length, RUNTIME_EVENT_HISTORY_LIMIT, 'runtime event history keeps the total cap when high-frequency events flood')
  assert.ok(
    explanatoryHistory.some((event) => event.conversationId === 'history-explanatory-route'),
    'runtime event history preserves explanatory events when token usage floods the cap'
  )
  assert.ok(RUNTIME_EVENT_EXPLANATORY_HISTORY_RESERVE > 0, 'runtime event history reserves capacity for explanatory events')
  localFileFixtures.set(uri, Buffer.from(`${'x'.repeat(5000)}\n`))
  await appendRuntimeLog('compact.usage', { providerId: 'openai-main', status: 'completed' }, { enabled: true, maxBytes: 4096 })
  assert.ok((localFileFixtures.get(uri)?.length ?? 0) <= 4096, 'runtime log rotation respects max bytes')
  localFileFixtures.set(uri, Buffer.from(`${'运行日志'.repeat(1800)}\n`))
  await appendRuntimeLog('compact.usage', { providerId: 'openai-main', status: 'completed' }, { enabled: true, maxBytes: 4096 })
  assert.ok((localFileFixtures.get(uri)?.length ?? 0) <= 4096, 'runtime log rotation respects UTF-8 byte limits')
  const info = await getRuntimeLogInfo()
  assert.equal(info.exists, true, 'runtime log info detects the current log file')
  assert.equal(info.path, uri, 'runtime log info returns the same path')
  assert.ok((await readRuntimeLogText()).includes('compact.usage'), 'runtime log tail reads recent events')
  localFileFixtures.set(uri, Buffer.from([
    JSON.stringify({ index: 1, note: 'x'.repeat(13000) }),
    JSON.stringify({ index: 2, event: 'upstream.request' }),
    JSON.stringify({ index: 3, event: 'upstream.response' }),
    '',
  ].join('\n'), 'utf8'))
  const parsedTailEntries = (await readRuntimeLogText())
    .trim()
    .split('\n')
    .filter(Boolean)
    .map((line) => JSON.parse(line))
  assert.deepEqual(parsedTailEntries.map((entry) => entry.index), [2, 3], 'runtime log tail drops truncated leading fragments and keeps full JSONL lines')
  await clearRuntimeLog()
  assert.equal(localFileFixtures.has(uri), false, 'runtime log clear deletes the log file')

  await Promise.all([
    appendRuntimeLog('upstream.request', { providerId: 'openai-main', model: 'gpt-5.2', requestId: 'req-1' }, { enabled: true, maxBytes: 4096 }),
    appendRuntimeLog('upstream.response', { providerId: 'openai-main', model: 'gpt-5.2', requestId: 'req-1', status: 200 }, { enabled: true, maxBytes: 4096 }),
  ])
  const concurrentEntries = (localFileFixtures.get(uri)?.toString('utf8') ?? '')
    .trim()
    .split('\n')
    .filter(Boolean)
    .map((line) => JSON.parse(line))
  assert.deepEqual(
    concurrentEntries.map((entry) => entry.event),
    ['upstream.request', 'upstream.response'],
    'runtime log serializes concurrent appends without dropping entries'
  )

  const appendThenClear = appendRuntimeLog('compact.usage', { providerId: 'openai-main', status: 'completed' }, { enabled: true, maxBytes: 4096 })
  const clearWhileAppendPending = clearRuntimeLog()
  await Promise.all([appendThenClear, clearWhileAppendPending])
  assert.equal(localFileFixtures.has(uri), false, 'runtime log clear waits for pending writes before deleting the file')
}

