      cancelledFallbackSignal = init?.signal
      resolveCancelledFallbackRequestStarted()
      return new Promise((_resolve, reject) => {
        rejectCancelledFallbackRequest = reject
        init?.signal?.addEventListener('abort', () => reject(init.signal.reason), { once: true })
      })
