    assert.equal(cancelledFallbackSignal?.aborted, true, 'selected runtime fallback abort reaches the in-flight transport request')
    assert.equal(cancelledFallbackSignal?.reason, cancelledFallbackReason, 'selected runtime fallback preserves the exact cancellation reason through the timeout transport')
