    assert.equal(injectedHttpSignal, pendingHttpAbort.controller.signal, 'normal HTTP runtime forwards the exact caller signal to the transport port')
    assert.equal(injectedHttpSignal.reason, httpAbortReason, 'normal HTTP transport observes the exact cancellation reason')
    assertInjectedAbortHasNoEffects(pendingHttpAbort, 0, 'normal HTTP cancellation')

