    assert.equal(traceAbortedNonStreamingFallback.citations.length, 0, 'non-streaming trace cancellation emits no late citations')
    assert.equal(traceAbortedNonStreamingFallback.completions.length, 0, 'non-streaming trace cancellation emits no completion')
    assert.equal(traceAbortedNonStreamingFallback.errors.length, 0, 'non-streaming trace cancellation emits no user-facing error')

