    assert.equal(traceAbortedNoReaderFallback.citations.length, 0, 'no-reader fallback trace cancellation emits no late citations')
    assert.equal(traceAbortedNoReaderFallback.completions.length, 0, 'no-reader fallback trace cancellation emits no completion')
    assert.equal(traceAbortedNoReaderFallback.errors.length, 0, 'no-reader fallback trace cancellation emits no user-facing error')
