    lastTestModel: 'gpt-5.5-mini',
    credentialGroups: [
      { id: 'policy-group', label: 'Policy Group', apiKey: FAKE_KEY_B, enabled: true, lastModelSyncStatus: 'ok', availableModels: ['blocked-chat', 'gpt-5.5-mini', 'gpt-4o', 'fast'] },
    ],
