  localFileFixtures.set('file:///tmp/islemind-models/all-MiniLM-L6-v2/model.onnx', Buffer.from('fake-model'))
  localFileFixtures.set('file:///cache/IsleMind-clear-all.apk', Buffer.from('apk'))
