  const githubTextResponse = (body, status = 200) => {
    const text = typeof body === 'string' ? body : JSON.stringify(body)
    return {
      ok: status >= 200 && status < 300,
      status,
      headers: { get: (name) => name.toLowerCase() === 'content-length' ? String(Buffer.byteLength(text, 'utf8')) : null },
      text: async () => text,
    }
  }
  const githubTagsAtom = (tags) => `<?xml version="1.0" encoding="UTF-8"?>
    <feed xmlns="http://www.w3.org/2005/Atom">
      ${tags.map((tag) => `<entry><id>tag:github.com,2008:Repository/1239979269/${tag}</id><updated>2026-06-05T00:00:00Z</updated><link rel="alternate" type="text/html" href="https://github.com/domidoremi/IsleMind/releases/tag/${tag}"/><title>IsleMind ${tag}</title></entry>`).join('')}
    </feed>`
  const githubReleaseAssetsHtml = (tagName, names) => `<div>${names.map((name) => `<a href="/domidoremi/IsleMind/releases/download/${tagName}/${encodeURIComponent(name)}">${name}</a>`).join('')}</div>`
  const createGithubTagFetch = ({ tagName, versionName, versionCode, manifest, assetNames, requests }) => async (url) => {
    const target = String(url)
    requests.push(target)
    if (target.endsWith('/tags.atom')) return githubTextResponse(githubTagsAtom(['v0.0.1', tagName]))
    if (target.endsWith(`/${tagName}/app.json`)) {
      return githubTextResponse({ expo: { version: versionName, android: { versionCode } } })
    }
    if (target.endsWith(`/${tagName}/updates/android.json`)) return githubTextResponse(manifest)
    if (target.endsWith(`/releases/expanded_assets/${tagName}`)) {
      return githubTextResponse(githubReleaseAssetsHtml(tagName, assetNames))
    }
    return githubTextResponse('', 404)
  }

