    assert.ok(updateFetchUrls.some((url) => url.endsWith('/v0.0.7/updates/android.json')), 'APK manifest is read from the selected immutable tag')
    assert.ok(updateFetchUrls.some((url) => url.endsWith('/releases/expanded_assets/v0.0.7')), 'actual tagged release assets are verified before download is offered')
