  streamProjection.flush()
  assert.deepEqual(streamProjectionEvents.at(-1), {
    type: 'text',
    ...streamIdentity,
    text: '!',
  }, 'assistant stream projection flushes pending text before traces on terminal cleanup')
  assert.equal(scheduledStreamFlushes.every((scheduled) => scheduled.cancelled), true, 'assistant stream projection cancels every scheduled flush during immediate or terminal projection')
  assert.deepEqual(streamIdentity, {
    conversationId: 'conversation-stream-projection',
    responseMessageId: 'assistant-stream-projection',
  }, 'assistant stream projection does not mutate caller identity')
  assert.deepEqual(firstRunningTrace.metadata, { phase: 'one' }, 'assistant stream projection does not mutate caller trace input')

  const providerStreamLifecycleEvents = []
  let providerStreamActive
  let settleProviderStream
  let providerStreamCallbacks
  const providerStreamDone = new Promise((resolve) => {
    settleProviderStream = resolve
  })
  const providerStreamController = new AbortController()
  const providerStreamRequestController = new AbortController()
  const providerStreamRequest = Object.freeze({
    model: 'provider-stream-model',
    signal: providerStreamRequestController.signal,
  })
  const providerStreamResult = Object.freeze({ text: 'provider stream result' })
  const providerStreamCitations = Object.freeze([
    Object.freeze({ id: 'provider-stream-citation', title: 'Citation' }),
  ])
  const providerStreamTrace = Object.freeze({
    id: 'provider-stream-trace',
    type: 'system',
    title: 'Provider trace',
    status: 'running',
  })
  let completedProviderStream
  let completedProviderLifecycle
  let projectedProviderCitations
  const providerStreamRuntime = createAssistantConversationProviderStreamingRuntime({
    createProjection(identity) {
      providerStreamLifecycleEvents.push(['projection', identity])
      return {
        pushText(chunk) {
          providerStreamLifecycleEvents.push(['text', chunk])
        },
        pushTrace(trace) {
          providerStreamLifecycleEvents.push(['trace', trace])
        },
        flush() {
          providerStreamLifecycleEvents.push(['flush'])
        },
      }
    },
    async dispatch(request, onChunk, onDone, onError, onCitations, onTrace) {
      providerStreamLifecycleEvents.push(['dispatch', request])
      providerStreamCallbacks = { onChunk, onDone, onError, onCitations, onTrace }
      return { controller: providerStreamController, done: providerStreamDone }
    },
    getActiveStream() {
      return providerStreamActive
    },
    setActiveStream(_conversationId, handle) {
      providerStreamActive = handle
      providerStreamLifecycleEvents.push(['set-active', handle])
    },
    clearActiveStream() {
      providerStreamActive = undefined
      providerStreamLifecycleEvents.push(['clear-active'])
    },
    isMessageCancelled() {
      return false
    },
  })
  const providerStreamOutcome = await providerStreamRuntime.start({
    conversationId: 'provider-stream-conversation',
    assistantMessageId: 'provider-stream-assistant',
    request: providerStreamRequest,
    requestController: providerStreamRequestController,
    async complete(result, lifecycle) {
      completedProviderStream = result
      completedProviderLifecycle = lifecycle
      providerStreamLifecycleEvents.push(['complete', result])
    },
    completionFailed(error) {
      throw error
    },
    providerFailed(error) {
      throw error
    },
    citations(citations) {
      projectedProviderCitations = citations
      providerStreamLifecycleEvents.push(['citations', citations])
    },
    startFailed(error) {
      throw error
    },
  })
  assert.equal(providerStreamOutcome.kind, 'started', 'assistant provider streaming runtime returns a typed started outcome')
  assert.equal(providerStreamOutcome.handle.controller, providerStreamController, 'assistant provider streaming runtime returns the exact provider controller')
  assert.equal(providerStreamOutcome.handle.done, providerStreamDone, 'assistant provider streaming runtime returns the exact provider done promise')
  assert.equal(providerStreamLifecycleEvents[0][0], 'projection', 'assistant provider streaming runtime creates its projection before active registration')
  assert.equal(providerStreamLifecycleEvents[1][0], 'set-active', 'assistant provider streaming runtime registers the request controller before dispatch')
  assert.equal(providerStreamLifecycleEvents[1][1].controller, providerStreamRequestController, 'assistant provider streaming runtime registers the exact request controller before dispatch')
  assert.equal(providerStreamLifecycleEvents[2][0], 'dispatch', 'assistant provider streaming runtime dispatches only after request-controller registration')
  assert.equal(providerStreamLifecycleEvents[2][1], providerStreamRequest, 'assistant provider streaming runtime forwards the exact provider request')
  assert.equal(providerStreamRequest.signal, providerStreamRequestController.signal, 'assistant provider streaming request retains the exact request signal')
  assert.equal(providerStreamActive.controller, providerStreamController, 'assistant provider streaming runtime replaces the request controller with the exact provider controller')
  assert.equal(providerStreamActive.done, providerStreamDone, 'assistant provider streaming runtime registers the exact provider done promise')
  providerStreamCallbacks.onChunk('provider stream chunk')
  providerStreamCallbacks.onTrace(providerStreamTrace)
  providerStreamCallbacks.onCitations(providerStreamCitations)
  providerStreamCallbacks.onDone(providerStreamResult)
  assert.equal(providerStreamLifecycleEvents.at(-4)[1], 'provider stream chunk', 'assistant provider streaming runtime routes provider chunks unchanged')
  assert.equal(providerStreamLifecycleEvents.at(-3)[1], providerStreamTrace, 'assistant provider streaming runtime routes the exact provider trace')
  assert.equal(projectedProviderCitations, providerStreamCitations, 'assistant provider streaming runtime routes the exact citation array')
  assert.equal(completedProviderStream, providerStreamResult, 'assistant provider streaming runtime routes the exact completion result')
  assert.equal(completedProviderLifecycle.requestController, providerStreamRequestController, 'assistant provider streaming completion receives the exact request controller')
  assert.equal(completedProviderLifecycle.flush, providerStreamActive.flush, 'assistant provider streaming completion receives the exact registered flush function')

  const providerReplacement = { controller: new AbortController(), messageId: 'replacement-stream' }
  providerStreamActive = providerReplacement
  settleProviderStream()
  await providerStreamDone
  await new Promise((resolve) => setImmediate(resolve))
  assert.equal(providerStreamLifecycleEvents.at(-1)[0], 'flush', 'assistant provider streaming settlement flushes buffered projections')
  assert.equal(providerStreamActive, providerReplacement, 'assistant provider streaming settlement preserves a replacement active stream')

