  const originalModelDiscoveryFetch = global.fetch
  const modelDiscoveryCalls = []
  global.fetch = async (url, init) => {
    modelDiscoveryCalls.push({ url: String(url), headers: init?.headers })
    return new Response(JSON.stringify({
      models: [
        { name: 'models/gemini-remote', displayName: 'Gemini Remote', inputTokenLimit: 300000, outputTokenLimit: 32000, supportedGenerationMethods: ['generateContent'] },
        { name: 'models/text-embedding-remote', displayName: 'Embedding Remote', supportedGenerationMethods: ['embedContent'] },
      ],
    }), { status: 200, headers: { 'content-type': 'application/json' } })
  }
  try {
    const remoteGoogleModels = await discoverProviderModels({
      id: 'google-remote',
      type: 'google',
      name: 'Google Remote',
      [API_KEY_FIELD]: 'google-key-test',
      models: [],
      enabled: true,
    }, 1000)
    assert.deepEqual(remoteGoogleModels.map((model) => model.id), ['gemini-remote'], 'provider model discovery remote helper filters Google non-chat models')
    assert.equal(remoteGoogleModels[0].contextWindow, 300000, 'provider model discovery remote helper preserves Google input limits')
    assert.equal(modelDiscoveryCalls[0].url, 'https://generativelanguage.googleapis.com/v1beta/models', 'provider model discovery remote helper keeps Google credentials out of the URL')
    assert.equal(modelDiscoveryCalls[0].headers['x-goog-api-key'], 'google-key-test', 'provider model discovery remote helper sends the documented Google API-key header')
  } finally {
    global.fetch = originalModelDiscoveryFetch
  }
  const originalCancelledModelDiscoveryFetch = global.fetch
  const modelDiscoveryAbortController = new AbortController()
  let modelDiscoveryTransportSignal
  try {
    global.fetch = async (_url, init = {}) => {
      modelDiscoveryTransportSignal = init.signal
      return new Promise((_resolve, reject) => {
        init.signal.addEventListener('abort', () => reject(new DOMException('Aborted', 'AbortError')), { once: true })
      })
    }
    const cancelledDiscovery = discoverProviderModels({
      id: 'google-cancelled-discovery',
      type: 'google',
      name: 'Google Cancelled Discovery',
      [API_KEY_FIELD]: 'google-key-test',
      models: [],
      enabled: true,
    }, 1000, modelDiscoveryAbortController.signal)
    await Promise.resolve()
    modelDiscoveryAbortController.abort()
    await assert.rejects(cancelledDiscovery, (error) => error?.name === 'AbortError', 'target provider model discovery propagates cancellation')
  } finally {
    global.fetch = originalCancelledModelDiscoveryFetch
  }
  assert.equal(modelDiscoveryTransportSignal?.aborted, true, 'provider model discovery aborts its transport signal')
  await assert.rejects(
    () => discoverProviderModels({
      id: 'invalid-discovery',
      type: 'openai-compatible',
      name: 'Invalid Discovery',
      [API_KEY_FIELD]: 'token-test-fake',
      baseUrl: 'file:///tmp/provider',
      models: [],
      enabled: true,
    }, 1000),
    /invalidBaseUrl/,
    'provider model discovery rejects invalid custom base URLs before fetch'
  )
