  assert.ok(/event:\s*["']context\.compact\.decided["']/.test(contextPlannerSource), 'context planner emits compact decision runtime events')

  const compactStateRepositorySource = fs.readFileSync(path.join(root, 'src/modules/providers/providerCompactStateRepository.ts'), 'utf8')
  const compactStateBindingSource = fs.readFileSync(path.join(root, 'src/bootstrap/providerCompactStateRepository.ts'), 'utf8')
  assert.ok(compactStateRepositorySource.includes('contextFragmentIdentitiesJson'), 'target compact state persists bounded context fragment identities')
  assert.ok(compactStateBindingSource.includes('createProviderCompactStateRepository'), 'bootstrap owns concrete compact-state persistence composition')
  assert.match(compactStateBindingSource, /useNewConnection: true,[\s\S]*finalizeUnusedStatementsBeforeClosing: false/, 'compact-state persistence disables Expo close-time FTS statement sweeping on its isolated connection')
