async function assertProviderStreamParsingMigrationBehavior() {
  const providerStreamParsingSource = fs.readFileSync(path.join(root, 'src/modules/providers/providerStreamParsing.ts'), 'utf8')
  const providerRuntimeExecutorSource = fs.readFileSync(path.join(root, 'src/bootstrap/providerRuntimeExecutor.ts'), 'utf8')
  assert.ok(providerStreamParsingSource.includes('export function createProviderStreamParsingPolicy'), 'target provider module owns stream event parsing behind injected presentation dependencies')
  assert.equal(fs.existsSync(path.join(root, 'src/services/ai/providerStreamParsing.ts')), false, 'legacy provider stream parser is deleted after target composition coverage')
  assert.equal(fs.existsSync(path.join(root, 'src/services/ai/providerStreamUtils.ts')), false, 'legacy provider stream utility facade is deleted after target composition coverage')
  assert.equal(providerStreamParsingSource.includes('extractProviderStreamContent'), false, 'dead provider stream text-only facade is not re-exported by the target module')
  assert.ok(providerRuntimeExecutorSource.includes('if (parsed.terminal)'), 'bootstrap provider execution consumes target-owned terminal stream markers')
  assert.ok(providerRuntimeExecutorSource.includes('cancelReaderAfterTerminal()'), 'terminal stream completion releases the reader without waiting for transport EOF')
  assert.ok(providerRuntimeExecutorSource.includes('if (completionDelivered) return'), 'terminal and EOF completion share an exactly-once guard')
  assert.ok(providerRuntimeExecutorSource.includes('TERMINAL_READER_CLOSE_GRACE_MS'), 'terminal reader cleanup gives a normally closing native stream a bounded close grace period')
  assert.ok(providerRuntimeExecutorSource.includes('const closed = terminalReader.closed'), 'terminal reader cleanup observes normal stream closure before attempting cancellation')

  const reasoningSuppressedStreamChunk = parseProviderStreamChunkForTest([
    `data: ${JSON.stringify({
      choices: [{ delta: { content: 'Visible answer.', reasoning_content: 'Hidden reasoning.' } }],
      usage: {
        prompt_tokens: 3,
        completion_tokens: 4,
        total_tokens: 7,
        completion_tokens_details: { reasoning_tokens: 2 },
      },
    })}`,
    'data: {malformed-json}',
    'data: [DONE]',
    '',
  ].join('\r\n'), 'openai-compatible', { includeReasoning: false })
  assert.equal(reasoningSuppressedStreamChunk.text, 'Visible answer.', 'provider stream parsing tolerates malformed CRLF SSE lines while retaining visible text')
  assert.equal(reasoningSuppressedStreamChunk.reasoningContent, undefined, 'provider stream parsing suppresses replayable reasoning content when reasoning is not admitted')
  assert.equal(reasoningSuppressedStreamChunk.traces.some((trace) => trace.type === 'reasoning'), false, 'provider stream parsing suppresses reasoning traces when reasoning is not admitted')
  assert.equal(reasoningSuppressedStreamChunk.usage.reasoningTokens, undefined, 'provider stream parsing suppresses reasoning-token usage when reasoning is not admitted')
  assert.equal(reasoningSuppressedStreamChunk.terminal, true, 'provider stream parsing reports the SSE terminal marker while retaining preceding content and usage')

  const standardsCompliantStreamChunk = parseProviderStreamChunkForTest([
    ': keep-alive',
    'data:{"choices":[{"delta":',
    'data:{"content":"Multiline SSE answer."}}]}',
    'data:[DONE]',
    '',
  ].join('\r'), 'openai-compatible')
  assert.equal(standardsCompliantStreamChunk.text, 'Multiline SSE answer.', 'provider stream parsing accepts comments, CR framing, optional data spacing, and multiline data fields')
  assert.equal(standardsCompliantStreamChunk.terminal, true, 'standards-compliant multiline SSE retains the terminal marker')

  const redactedReasoningStreamEvent = parseProviderStreamEventForTest({
    choices: [{ delta: { reasoning_content: 'api_key=sk-provider-stream-secret' } }],
  }, 'openai-compatible')
  assert.equal(redactedReasoningStreamEvent.traces[0]?.title, st('providerTrace.reasoningSummary'), 'provider stream parsing keeps the localized reasoning trace title from bootstrap composition')
  assert.doesNotMatch(redactedReasoningStreamEvent.traces[0]?.content ?? '', /sk-provider-stream-secret/, 'provider stream parsing redacts sensitive reasoning trace content at the composed boundary')
  assert.match(redactedReasoningStreamEvent.traces[0]?.content ?? '', /\[redacted\]/, 'provider stream parsing retains explicit redaction evidence')

  assert.deepEqual(
    splitSseBuffer('data: one\r\n\r\ndata: two\r\n\r\ndata: partial'),
    { events: ['data: one', 'data: two'], remainder: 'data: partial' },
    'provider stream utility normalizes CRLF SSE chunks and preserves partial remainder'
  )
  const fragmentedCrLf = splitSseBuffer('data: one\r\rdata: two\r')
  assert.deepEqual(fragmentedCrLf, { events: ['data: one'], remainder: 'data: two\r' }, 'provider stream utility keeps a trailing CR pending across transport chunks')
  assert.deepEqual(
    splitSseBuffer(`${fragmentedCrLf.remainder}\n\r\n`),
    { events: ['data: two'], remainder: '' },
    'provider stream utility reconstructs a fragmented CRLF event boundary without inventing a blank line'
  )
  assert.deepEqual(
    dedupeTraces([
      { id: 'trace-a', type: 'reasoning', title: 'Trace', content: 'A', status: 'running', timestamp: 1 },
      { id: 'trace-a', type: 'reasoning', title: 'Trace', content: 'A again', status: 'running', timestamp: 2 },
      { type: 'tool', title: 'Tool', content: 'B', status: 'done', timestamp: 3 },
      { type: 'tool', title: 'Tool', content: 'B', status: 'done', timestamp: 4 },
    ]).map((trace) => trace.timestamp),
    [1, 3],
    'provider stream utility dedupes traces by id or fallback trace shape'
  )

  const encoder = new TextEncoder()
  let readerCancelCount = 0
  let resolveReaderCancellation
  const readerCancellation = new Promise((resolve) => {
    resolveReaderCancellation = resolve
  })
  const neverClosingStream = new ReadableStream({
    start(controller) {
      controller.enqueue(encoder.encode([
        `data: ${JSON.stringify({ choices: [{ delta: { content: 'Terminal stream answer.' } }] })}`,
        `data: ${JSON.stringify({
          choices: [{
            delta: {
              tool_calls: [{
                index: 0,
                id: 'call-terminal-stream',
                type: 'function',
                function: { name: 'terminal_stream_probe', arguments: '{"value":"retained"}' },
              }],
            },
          }],
        })}`,
        `data: ${JSON.stringify({
          usage: { prompt_tokens: 5, completion_tokens: 3, total_tokens: 8 },
        })}`,
        'data: [DONE]',
        '',
      ].join('\r\n\r\n')))
    },
    cancel() {
      readerCancelCount += 1
      resolveReaderCancellation()
    },
  })
  const chunks = []
  const completions = []
  const errors = []
  const traces = []
  const controller = new AbortController()
  const execution = executeHttpSseChatForTest({
    req: {
      provider: {
        id: 'terminal-stream-provider',
        type: 'openai-compatible',
        name: 'Terminal Stream Provider',
        apiKey: FAKE_KEY_A,
        baseUrl: 'https://terminal-stream.invalid/v1',
        models: ['terminal-stream-model'],
        enabled: true,
      },
      model: 'terminal-stream-model',
      messages: [{ role: 'user', content: 'complete on the terminal marker' }],
      stream: true,
      settings: { upstreamMaxRetries: 0, upstreamCircuitBreakerEnabled: false },
    },
    url: 'https://terminal-stream.invalid/v1/chat/completions',
    headers: { Authorization: `Bearer ${FAKE_KEY_A}` },
    body: JSON.stringify({ model: 'terminal-stream-model', stream: true }),
    stream: true,
    controller,
    resolveRoute: () => ({ body: {} }),
    onChunk: (chunk) => chunks.push(chunk),
    onDone: (result) => completions.push(result),
    onError: (error) => errors.push(error),
    onTrace: (trace) => traces.push(trace),
    transport: {
      requestStream: async () => new Response(neverClosingStream, {
        status: 200,
        headers: { 'content-type': 'text/event-stream' },
      }),
      readResponseText: (response) => response.text(),
    },
    buildFallbackCandidates: () => ({ candidates: [], evidence: [], rejectedCandidates: [] }),
    fallbackEffects: {
      logDecision: async () => undefined,
      recordRouteFailure: async () => undefined,
      recordRouteSuccess: async () => undefined,
    },
  })
  let timeout
  try {
    await Promise.race([
      execution,
      new Promise((_, reject) => {
        timeout = setTimeout(() => reject(new Error('provider terminal marker did not settle before transport EOF')), 1000)
      }),
    ])
  } finally {
    clearTimeout(timeout)
  }
  let cancellationTimeout
  try {
    await Promise.race([
      readerCancellation,
      new Promise((_, reject) => {
        cancellationTimeout = setTimeout(() => reject(new Error('provider terminal reader was not cancelled after the close grace period')), 1000)
      }),
    ])
  } finally {
    clearTimeout(cancellationTimeout)
  }

  assert.deepEqual(chunks, ['Terminal stream answer.'], 'terminal-marker completion preserves all visible content emitted before the marker')
  assert.equal(readerCancelCount, 1, 'terminal-marker completion cancels the never-closing reader exactly once')
  assert.equal(completions.length, 1, 'terminal-marker completion delivers exactly one completion')
  assert.equal(errors.length, 0, 'terminal-marker completion does not emit a failure')
  assert.deepEqual(
    completions[0].usage,
    { inputTokens: 5, outputTokens: 3, totalTokens: 8, source: 'provider' },
    'terminal-marker completion preserves the final usage event',
  )
  assert.equal(completions[0].providerToolCalls?.[0]?.name, 'terminal_stream_probe', 'terminal-marker completion preserves streamed provider tool calls')
  assert.ok(completions[0].traces.some((trace) => trace.type === 'tool'), 'terminal-marker completion preserves streamed provider traces')
  assert.ok(traces.some((trace) => trace.type === 'tool'), 'terminal-marker completion projects streamed traces before settling')

  let resolveNormallyClosingReader
  const normallyClosingReaderClosed = new Promise((resolve) => {
    resolveNormallyClosingReader = resolve
  })
  let normallyClosingReadCount = 0
  let normallyClosingCancelCount = 0
  const normallyClosingChunks = []
  const normallyClosingCompletions = []
  const normallyClosingErrors = []
  const normallyClosingPayload = [
    `data: ${JSON.stringify({ choices: [{ delta: { content: 'Normally closed stream.' } }] })}`,
    'data: [DONE]',
    '',
  ].join('\n\n')
  await executeHttpSseChatForTest({
    req: {
      provider: {
        id: 'normally-closing-provider',
        type: 'openai-compatible',
        name: 'Normally Closing Provider',
        apiKey: FAKE_KEY_A,
        baseUrl: 'https://normally-closing.invalid/v1',
        models: ['normally-closing-model'],
        enabled: true,
      },
      model: 'normally-closing-model',
      messages: [{ role: 'user', content: 'allow native close after the terminal marker' }],
      stream: true,
      settings: { upstreamMaxRetries: 0, upstreamCircuitBreakerEnabled: false },
    },
    url: 'https://normally-closing.invalid/v1/chat/completions',
    headers: { Authorization: `Bearer ${FAKE_KEY_A}` },
    body: JSON.stringify({ model: 'normally-closing-model', stream: true }),
    stream: true,
    controller: new AbortController(),
    resolveRoute: () => ({ body: {} }),
    onChunk: (chunk) => normallyClosingChunks.push(chunk),
    onDone: (result) => normallyClosingCompletions.push(result),
    onError: (error) => normallyClosingErrors.push(error),
    transport: {
      requestStream: async () => ({
        ok: true,
        status: 200,
        statusText: 'OK',
        headers: new Headers({ 'content-type': 'text/event-stream' }),
        body: {
          getReader: () => ({
            closed: normallyClosingReaderClosed,
            read: async () => {
              normallyClosingReadCount += 1
              queueMicrotask(resolveNormallyClosingReader)
              return { done: false, value: encoder.encode(normallyClosingPayload) }
            },
            cancel: async () => {
              normallyClosingCancelCount += 1
              throw new TypeError('The stream is not in a state that permits close')
            },
          }),
        },
      }),
      readResponseText: (response) => response.text(),
    },
    buildFallbackCandidates: () => ({ candidates: [], evidence: [], rejectedCandidates: [] }),
    fallbackEffects: {
      logDecision: async () => undefined,
      recordRouteFailure: async () => undefined,
      recordRouteSuccess: async () => undefined,
    },
  })
  await normallyClosingReaderClosed
  await new Promise((resolve) => setTimeout(resolve, 75))

  assert.equal(normallyClosingReadCount, 1, 'terminal completion does not read beyond the terminal marker while native closure settles')
  assert.equal(normallyClosingCancelCount, 0, 'a reader that closes during the grace period is not cancelled into the native close race')
  assert.deepEqual(normallyClosingChunks, ['Normally closed stream.'], 'normal reader closure preserves visible terminal content')
  assert.equal(normallyClosingCompletions.length, 1, 'normal reader closure delivers exactly one completion')
  assert.equal(normallyClosingErrors.length, 0, 'normal reader closure does not emit the native close race as a provider failure')

  let doneWithValueReadCount = 0
  let doneWithValueCancelCount = 0
  const doneWithValueChunks = []
  const doneWithValueCompletions = []
  const doneWithValueErrors = []
  const doneWithValuePayload = [
    `data: ${JSON.stringify({ choices: [{ delta: { content: 'Final reader value.' } }] })}`,
    `data: ${JSON.stringify({ usage: { prompt_tokens: 7, completion_tokens: 2, total_tokens: 9 } })}`,
    'data: [DONE]',
    '',
  ].join('\n\n')
  await executeHttpSseChatForTest({
    req: {
      provider: {
        id: 'done-with-value-provider',
        type: 'openai-compatible',
        name: 'Done With Value Provider',
        apiKey: FAKE_KEY_A,
        baseUrl: 'https://done-with-value.invalid/v1',
        models: ['done-with-value-model'],
        enabled: true,
      },
      model: 'done-with-value-model',
      messages: [{ role: 'user', content: 'preserve the final reader value' }],
      stream: true,
      settings: { upstreamMaxRetries: 0, upstreamCircuitBreakerEnabled: false },
    },
    url: 'https://done-with-value.invalid/v1/chat/completions',
    headers: { Authorization: `Bearer ${FAKE_KEY_A}` },
    body: JSON.stringify({ model: 'done-with-value-model', stream: true }),
    stream: true,
    controller: new AbortController(),
    resolveRoute: () => ({ body: {} }),
    onChunk: (chunk) => doneWithValueChunks.push(chunk),
    onDone: (result) => doneWithValueCompletions.push(result),
    onError: (error) => doneWithValueErrors.push(error),
    transport: {
      requestStream: async () => ({
        ok: true,
        status: 200,
        statusText: 'OK',
        headers: new Headers({ 'content-type': 'text/event-stream' }),
        body: {
          getReader: () => ({
            read: async () => {
              doneWithValueReadCount += 1
              return { done: true, value: encoder.encode(doneWithValuePayload) }
            },
            cancel: async () => {
              doneWithValueCancelCount += 1
            },
          }),
        },
      }),
      readResponseText: (response) => response.text(),
    },
    buildFallbackCandidates: () => ({ candidates: [], evidence: [], rejectedCandidates: [] }),
    fallbackEffects: {
      logDecision: async () => undefined,
      recordRouteFailure: async () => undefined,
      recordRouteSuccess: async () => undefined,
    },
  })

  assert.equal(doneWithValueReadCount, 1, 'provider execution reads a terminal value only once')
  assert.equal(doneWithValueCancelCount, 1, 'terminal bytes returned with done=true still release the reader')
  assert.deepEqual(doneWithValueChunks, ['Final reader value.'], 'provider execution decodes bytes returned together with done=true')
  assert.equal(doneWithValueCompletions.length, 1, 'done-with-value terminal completion settles exactly once')
  assert.equal(doneWithValueErrors.length, 0, 'done-with-value terminal completion emits no failure')
  assert.deepEqual(
    doneWithValueCompletions[0].usage,
    { inputTokens: 7, outputTokens: 2, totalTokens: 9, source: 'provider' },
    'done-with-value terminal completion preserves final usage',
  )
}

async function assertProviderRuntimeAndroidCollectorBehavior() {
  const collectorPath = path.join(root, 'scripts/collect-provider-runtime-android.js')
  const collectorSource = fs.readFileSync(collectorPath, 'utf8')
  assert.match(collectorSource, /async function assertProviderFailureServerSelfTest\(\)/, 'Provider Runtime Android collector exposes a deterministic worker/server self-test')
  assert.match(collectorSource, /fetch\(`\$\{providerFailureServer\.baseUrl\}\/chat\/completions`[\s\S]*method: 'POST'/, 'Provider Runtime Android self-test sends a POST chat completion request')
  assert.match(collectorSource, /response\.status !== 503/, 'Provider Runtime Android self-test requires the deterministic HTTP 503 response')
  assert.match(collectorSource, /entries\[0\]\.method !== 'POST'[\s\S]*entries\[0\]\.url !== '\/v1\/chat\/completions'[\s\S]*entries\[0\]\.status !== 503/, 'Provider Runtime Android self-test validates the bounded request record')
  assert.match(collectorSource, /clearAdbReverse\(device, providerFailureServer\.port\)[\s\S]*stopProviderFailureServer\(providerFailureServer\)/, 'Provider Runtime Android cleanup removes reverse before stopping the fixture')
  assert.match(collectorSource, /function hasRuntimeFallbackEventEvidence\(logText\)/, 'Provider Runtime Android collector isolates typed fallback event evidence')
  assert.match(collectorSource, /provider\\\.fallback\\\.decided\|fallback\\\.decision/, 'Provider Runtime Android collector accepts only the typed or legacy fallback event names')
  assert.match(collectorSource, /function hasRuntimeFallbackDiagnosticsEvidence\(uiaText\)/, 'Provider Runtime Android collector exposes bounded diagnostics fallback evidence')
  assert.match(collectorSource, /function hasProviderHealthDiagnosticsEvidence\(uiaText\)/, 'Provider Runtime Android collector exposes bounded provider-health diagnostics evidence')
  assert.match(collectorSource, /openRuntimeDiagnostics\(device, record, diagnosticsStart, 'provider-runtime-fallback'/, 'Provider Runtime Android fallback scenario opens nested runtime diagnostics')
  assert.match(collectorSource, /findRuntimeFallbackDiagnosticsEvidence\(device, record, capture/, 'Provider Runtime Android fallback scenario searches request examples after expansion')
  assert.match(collectorSource, /findProviderHealthDiagnosticsEvidence\(device, record, capture/, 'Provider Runtime Android health scenario searches provider-health diagnostics after expansion')
  assert.match(collectorSource, /const recoveryRequestMarker = 'QA_PROVIDER_RUNTIME_RECOVERY_REQUEST'/, 'Provider Runtime Android recovery uses a fixed non-secret request sentinel')
  assert.match(collectorSource, /const recoveryCompletionMarker = 'QA_PROVIDER_RUNTIME_RECOVERY_COMPLETE'/, 'Provider Runtime Android recovery uses a fixed non-secret completion sentinel')
  assert.match(collectorSource, /mcpEnabled: false,/, 'Provider Runtime Android recovery fixture disables MCP so the target plain-Chat runtime remains eligible')
  assert.match(collectorSource, /function runRestartRecovery\(device, providerFailureServer\)[\s\S]*inputText\(device, recoveryRequestMarker\)[\s\S]*captureRestartRecoveryDurableState\(device\)[\s\S]*openUrl\(device, `islemind:\/\/chat\/\$\{recoveryConversationId\}`\)/, 'Provider Runtime Android recovery sends, snapshots, and reopens one known Chat conversation')
  assert.match(collectorSource, /function captureRestartRecoveryDurableState\(device\)[\s\S]*'force-stop', appPackageName[\s\S]*'pull', contextDatabaseRemotePath/, 'Provider Runtime Android recovery force-stops before pulling a quiescent SQLite snapshot')
  assert.match(collectorSource, /FROM assistant_runs[\s\S]*WHERE conversationId = \? AND status = 'succeeded'/, 'Provider Runtime Android recovery reads a terminal AssistantRun for the known conversation')
  assert.match(collectorSource, /FROM assistant_run_journal[\s\S]*WHERE runId = \?/, 'Provider Runtime Android recovery reads the journal through the selected run identity')
  assert.match(collectorSource, /FROM conversation_records WHERE id = \? LIMIT 1/, 'Provider Runtime Android recovery reads the known durable conversation record')
  assert.match(collectorSource, /responseMessageId: run\.responseMessageId[\s\S]*outputMatched:/, 'Provider Runtime Android recovery records bounded run-to-message and output linkage')
  assert.match(collectorSource, /journal: journal\.map\(\(entry\) => \(\{[\s\S]*runId: entry\.runId/, 'Provider Runtime Android recovery records journal-to-run linkage')
  assert.match(collectorSource, /restart recovery conversation identity[\s\S]*restart recovery ordinary chat kind[\s\S]*restart recovery terminal run state[\s\S]*restart recovery journal linkage/, 'Provider Runtime Android self-test rejects unrelated, non-Chat, nonterminal, and unlinked recovery state')
  assert.doesNotMatch(collectorSource, /input', 'tap', '950', '2078'/, 'Provider Runtime Android collector does not use an emulator-size hardcoded send tap')
  assert.doesNotMatch(collectorSource, /hasRuntimeFallbackEvidence\('', capture\.uiaText\)/, 'Provider Runtime Android collector does not accept generic Chat text as fallback evidence')
  assert.doesNotMatch(collectorSource, /providerName\]\), 5\)/, 'Provider Runtime Android health scenario does not pass on the provider card alone')

  const selfTest = await new Promise((resolve, reject) => {
    const child = require('node:child_process').spawn(process.execPath, [collectorPath, '--self-test'], { cwd: root, stdio: ['ignore', 'pipe', 'pipe'] })
    let stdout = ''
    let stderr = ''
    child.stdout.on('data', (chunk) => { stdout += chunk })
    child.stderr.on('data', (chunk) => { stderr += chunk })
    child.on('error', reject)
    child.on('close', (code) => code === 0 ? resolve(`${stdout}${stderr}`) : reject(new Error(`collector self-test exited ${code}: ${stdout}${stderr}`)))
  })
  assert.match(selfTest, /Provider Runtime Android self-test passed \(9 required scenarios\)\./, 'Provider Runtime Android collector self-test passes')
}

